$script:EmbeddedWinTweaksJson = @'
{
  "WPFTweaksDisableGameDVR": {
    "title": "Desativar Xbox Game DVR e Grava\u00e7\u00e3o em 2\u00ba Plano",
    "category": "Desempenho & Energia",
    "description": "Desativa a grava\u00e7\u00e3o cont\u00ednua de tela do Xbox Game Bar, reduzindo o uso de GPU/V\u00eddeo e eliminando micro-stutterings em jogos.",
    "rationale": "O recurso Historical Capture mant\u00e9m sess\u00f5es de codifica\u00e7\u00e3o de v\u00eddeo (NVENC/AMF) e buffers D3D ativos em segundo plano. Este tweak altera apenas HKCU, preservando a Xbox Game Bar e a detec\u00e7\u00e3o de jogos usada pelo AMD 3D V-Cache Optimizer. A policy de m\u00e1quina AllowGameDVR fica em um tweak separado, bloqueado em Ryzen X3D dual-CCD.",
    "impact": "M\u00e9dio",
    "riskLevel": "Safe",
    "osSupport": ["Win10", "Win11"],
    "minBuild": null,
    "requiresReboot": false,
    "confirmMessage": null,
    "registry": [
      {
        "path": "HKCU:\\System\\GameConfigStore",
        "name": "GameDVR_Enabled",
        "type": "DWord",
        "value": 0,
        "originalValue": 1
      },
      {
        "path": "HKCU:\\Software\\Microsoft\\Windows\\CurrentVersion\\GameDVR",
        "name": "AppCaptureEnabled",
        "type": "DWord",
        "value": 0,
        "originalValue": 1
      }
    ],
    "services": [],
    "scheduledTasks": [],
    "appx": [],
    "invokeScript": [],
