$script:EmbeddedThemeXaml = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="OptiKit"
        Width="1240" Height="850"
        MinWidth="980" MinHeight="660"
        WindowStartupLocation="CenterScreen"
        Background="{DynamicResource Brush.Bg.Window}"
        Foreground="{DynamicResource Brush.Text.Primary}"
        FontFamily="Segoe UI"
        FontSize="14"
        UseLayoutRounding="True"
        TextOptions.TextFormattingMode="Display">

    <Window.Resources>
        <!-- Paleta: neutros frios, um acento e tr&#x00EA;s cores de estado. Nenhum hex fora deste bloco. -->
        <SolidColorBrush x:Key="Brush.Bg.Window" Color="#111214" />
        <SolidColorBrush x:Key="Brush.Bg.Rail" Color="#16171A" />
        <SolidColorBrush x:Key="Brush.Bg.Surface" Color="#1B1D20" />
        <SolidColorBrush x:Key="Brush.Bg.Hover" Color="#212328" />
        <SolidColorBrush x:Key="Brush.Bg.Pressed" Color="#282B30" />
        <SolidColorBrush x:Key="Brush.Border.Subtle" Color="#25272C" />
        <SolidColorBrush x:Key="Brush.Border.Default" Color="#363940" />
        <SolidColorBrush x:Key="Brush.Text.Primary" Color="#ECEDEF" />
        <SolidColorBrush x:Key="Brush.Text.Secondary" Color="#A4A9B0" />
        <SolidColorBrush x:Key="Brush.Text.Tertiary" Color="#8A8F97" />
        <SolidColorBrush x:Key="Brush.Text.Disabled" Color="#5C6168" />
        <SolidColorBrush x:Key="Brush.Accent" Color="#2BC4E0" />
        <SolidColorBrush x:Key="Brush.Accent.Hover" Color="#55D3EA" />
        <SolidColorBrush x:Key="Brush.Accent.Pressed" Color="#1FA6C0" />
        <SolidColorBrush x:Key="Brush.OnAccent" Color="#0B0D10" />
        <SolidColorBrush x:Key="Brush.Success" Color="#3FB97A" />
        <SolidColorBrush x:Key="Brush.Warning" Color="#E0A43B" />
        <SolidColorBrush x:Key="Brush.Danger" Color="#E5534B" />

        <FontFamily x:Key="Font.Mono">Cascadia Mono, Consolas</FontFamily>
        <FontFamily x:Key="Font.Icon">Segoe Fluent Icons, Segoe MDL2 Assets</FontFamily>

        <!-- Tipografia: 4 tamanhos (12 / 14 / 16 / 20), 2 pesos (Regular / SemiBold). -->
        <Style x:Key="Text.Title" TargetType="TextBlock">
            <Setter Property="FontSize" Value="20" />
            <Setter Property="FontWeight" Value="SemiBold" />
            <Setter Property="Foreground" Value="{StaticResource Brush.Text.Primary}" />
        </Style>
        <Style x:Key="Text.Subtitle" TargetType="TextBlock">
            <Setter Property="FontSize" Value="16" />
            <Setter Property="FontWeight" Value="SemiBold" />
            <Setter Property="Foreground" Value="{StaticResource Brush.Text.Primary}" />
        </Style>
        <Style x:Key="Text.Body" TargetType="TextBlock">
            <Setter Property="FontSize" Value="14" />
            <Setter Property="Foreground" Value="{StaticResource Brush.Text.Primary}" />
        </Style>
        <Style x:Key="Text.BodyStrong" TargetType="TextBlock" BasedOn="{StaticResource Text.Body}">
            <Setter Property="FontWeight" Value="SemiBold" />
        </Style>
        <Style x:Key="Text.Caption" TargetType="TextBlock">
            <Setter Property="FontSize" Value="12" />
            <Setter Property="Foreground" Value="{StaticResource Brush.Text.Secondary}" />
        </Style>
        <Style x:Key="Text.Meta" TargetType="TextBlock" BasedOn="{StaticResource Text.Caption}">
            <Setter Property="Foreground" Value="{StaticResource Brush.Text.Tertiary}" />
        </Style>
        <Style x:Key="Text.Icon" TargetType="TextBlock">
            <Setter Property="FontFamily" Value="{StaticResource Font.Icon}" />
            <Setter Property="FontSize" Value="16" />
            <Setter Property="VerticalAlignment" Value="Center" />
        </Style>
        <Style x:Key="Nav.Icon" TargetType="TextBlock" BasedOn="{StaticResource Text.Icon}">
            <Setter Property="Margin" Value="0,0,12,0" />
        </Style>
        <Style x:Key="Section.Header" TargetType="TextBlock" BasedOn="{StaticResource Text.Subtitle}">
            <Setter Property="Margin" Value="0,24,0,4" />
        </Style>

        <Style x:Key="Divider" TargetType="Border">
            <Setter Property="Height" Value="1" />
            <Setter Property="Background" Value="{StaticResource Brush.Border.Subtle}" />
            <Setter Property="SnapsToDevicePixels" Value="True" />
        </Style>
        <Style x:Key="Action.Row" TargetType="DockPanel">
            <Setter Property="LastChildFill" Value="True" />
            <Setter Property="MinHeight" Value="64" />
        </Style>
        <Style x:Key="Action.Text" TargetType="StackPanel">
            <Setter Property="VerticalAlignment" Value="Center" />
            <Setter Property="Margin" Value="0,10,24,10" />
        </Style>
        <Style x:Key="Action.Buttons" TargetType="StackPanel">
            <Setter Property="Orientation" Value="Horizontal" />
            <Setter Property="VerticalAlignment" Value="Center" />
        </Style>

        <Style x:Key="FocusVisual.Accent">
            <Setter Property="Control.Template">
                <Setter.Value>
                    <ControlTemplate>
                        <Rectangle Margin="-2" RadiusX="5" RadiusY="5" Stroke="{StaticResource Brush.Accent}" StrokeThickness="1" SnapsToDevicePixels="True" />
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Bot&#x00F5;es: Secondary (padr&#x00E3;o), Primary (uma por tela), Subtle (a&#x00E7;&#x00F5;es de baixa &#x00EA;nfase), Danger (destrutiva). -->
        <Style x:Key="Button.Secondary" TargetType="Button">
            <Setter Property="Background" Value="{StaticResource Brush.Bg.Surface}" />
            <Setter Property="Foreground" Value="{StaticResource Brush.Text.Primary}" />
            <Setter Property="BorderBrush" Value="{StaticResource Brush.Border.Default}" />
            <Setter Property="BorderThickness" Value="1" />
            <Setter Property="Padding" Value="12,0" />
            <Setter Property="Height" Value="32" />
            <Setter Property="MinWidth" Value="72" />
            <Setter Property="FontSize" Value="14" />
            <Setter Property="Cursor" Value="Hand" />
            <Setter Property="FocusVisualStyle" Value="{StaticResource FocusVisual.Accent}" />
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="4" Padding="{TemplateBinding Padding}" SnapsToDevicePixels="True">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" />
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="Bd" Property="Background" Value="{StaticResource Brush.Bg.Hover}" />
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter TargetName="Bd" Property="Background" Value="{StaticResource Brush.Bg.Pressed}" />
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter Property="Foreground" Value="{StaticResource Brush.Text.Disabled}" />
                                <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource Brush.Border.Subtle}" />
                                <Setter Property="Cursor" Value="Arrow" />
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
        <Style TargetType="Button" BasedOn="{StaticResource Button.Secondary}" />

        <Style x:Key="Button.Primary" TargetType="Button" BasedOn="{StaticResource Button.Secondary}">
            <Setter Property="Background" Value="{StaticResource Brush.Accent}" />
            <Setter Property="Foreground" Value="{StaticResource Brush.OnAccent}" />
            <Setter Property="BorderBrush" Value="{StaticResource Brush.Accent}" />
            <Setter Property="FontWeight" Value="SemiBold" />
            <Setter Property="Padding" Value="16,0" />
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="4" Padding="{TemplateBinding Padding}" SnapsToDevicePixels="True">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" />
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="Bd" Property="Background" Value="{StaticResource Brush.Accent.Hover}" />
                                <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource Brush.Accent.Hover}" />
                            </Trigger>
                            <Trigger Property="IsPressed" Value="True">
                                <Setter TargetName="Bd" Property="Background" Value="{StaticResource Brush.Accent.Pressed}" />
                                <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource Brush.Accent.Pressed}" />
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="Bd" Property="Background" Value="{StaticResource Brush.Bg.Pressed}" />
                                <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource Brush.Bg.Pressed}" />
                                <Setter Property="Foreground" Value="{StaticResource Brush.Text.Disabled}" />
                                <Setter Property="Cursor" Value="Arrow" />
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="Button.Subtle" TargetType="Button" BasedOn="{StaticResource Button.Secondary}">
            <Setter Property="Background" Value="Transparent" />
            <Setter Property="BorderBrush" Value="Transparent" />
            <Setter Property="Foreground" Value="{StaticResource Brush.Text.Secondary}" />
            <Setter Property="MinWidth" Value="0" />
            <Setter Property="Padding" Value="10,0" />
            <Style.Triggers>
                <Trigger Property="IsMouseOver" Value="True">
                    <Setter Property="Foreground" Value="{StaticResource Brush.Text.Primary}" />
                </Trigger>
            </Style.Triggers>
        </Style>

        <Style x:Key="Button.Danger" TargetType="Button" BasedOn="{StaticResource Button.Secondary}">
            <Setter Property="Foreground" Value="{StaticResource Brush.Danger}" />
        </Style>

        <Style x:Key="Button.Icon" TargetType="Button" BasedOn="{StaticResource Button.Subtle}">
            <Setter Property="FontFamily" Value="{StaticResource Font.Icon}" />
            <Setter Property="FontSize" Value="10" />
            <Setter Property="Width" Value="28" />
            <Setter Property="Height" Value="28" />
            <Setter Property="Padding" Value="0" />
        </Style>

        <Style x:Key="Button.SearchClear" TargetType="Button" BasedOn="{StaticResource Button.Icon}">
            <Setter Property="Visibility" Value="Visible" />
            <Style.Triggers>
                <DataTrigger Binding="{Binding Text, ElementName=TxtSearchBox}" Value="">
                    <Setter Property="Visibility" Value="Collapsed" />
                </DataTrigger>
            </Style.Triggers>
        </Style>

        <!-- CheckBox em formato de linha: a linha inteira &#x00E9; clic&#x00E1;vel, com hover e caixa alinhada ao topo. -->
        <Style TargetType="CheckBox">
            <Setter Property="Foreground" Value="{StaticResource Brush.Text.Primary}" />
            <Setter Property="Background" Value="Transparent" />
            <Setter Property="Padding" Value="10,8" />
            <Setter Property="Cursor" Value="Hand" />
            <Setter Property="HorizontalContentAlignment" Value="Stretch" />
            <Setter Property="FocusVisualStyle" Value="{StaticResource FocusVisual.Accent}" />
            <Setter Property="ToolTipService.ShowDuration" Value="30000" />
            <Setter Property="ToolTipService.InitialShowDelay" Value="500" />
            <Setter Property="ToolTipService.ShowOnDisabled" Value="True" />
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="CheckBox">
                        <Border x:Name="Row" Background="{TemplateBinding Background}" CornerRadius="4" Padding="{TemplateBinding Padding}" SnapsToDevicePixels="True">
                            <Grid>
                                <Grid.ColumnDefinitions>
                                    <ColumnDefinition Width="Auto" />
                                    <ColumnDefinition Width="*" />
                                </Grid.ColumnDefinitions>
                                <Border x:Name="Box" Width="18" Height="18" Margin="0,1,12,0" VerticalAlignment="Top" CornerRadius="3" BorderThickness="1" BorderBrush="{StaticResource Brush.Border.Default}" Background="{StaticResource Brush.Bg.Surface}">
                                    <Path x:Name="Mark" Data="M 4,9 L 7.5,12.5 L 14,5.5" Stroke="{StaticResource Brush.OnAccent}" StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" Visibility="Collapsed" />
                                </Border>
                                <ContentPresenter Grid.Column="1" HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}" VerticalAlignment="Center" />
                            </Grid>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="Row" Property="Background" Value="{StaticResource Brush.Bg.Hover}" />
                                <Setter TargetName="Box" Property="BorderBrush" Value="{StaticResource Brush.Text.Tertiary}" />
                            </Trigger>
                            <Trigger Property="IsChecked" Value="True">
                                <Setter TargetName="Box" Property="Background" Value="{StaticResource Brush.Accent}" />
                                <Setter TargetName="Box" Property="BorderBrush" Value="{StaticResource Brush.Accent}" />
                                <Setter TargetName="Mark" Property="Visibility" Value="Visible" />
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="Row" Property="Opacity" Value="0.6" />
                                <Setter Property="Cursor" Value="Arrow" />
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- ComboBox escuro (o template padr&#x00E3;o do Aero2 ignora Background e deixava o texto ileg&#x00ED;vel). -->
        <Style x:Key="ComboBox.Toggle" TargetType="ToggleButton">
            <Setter Property="OverridesDefaultStyle" Value="True" />
            <Setter Property="Focusable" Value="False" />
            <Setter Property="ClickMode" Value="Press" />
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ToggleButton">
                        <Border Background="Transparent">
                            <Path HorizontalAlignment="Right" VerticalAlignment="Center" Margin="0,0,12,0" Data="M 0,0 L 4,4 L 8,0" Stroke="{StaticResource Brush.Text.Secondary}" StrokeThickness="1.5" StrokeStartLineCap="Round" StrokeEndLineCap="Round" />
                        </Border>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
        <Style TargetType="ComboBox">
            <Setter Property="Foreground" Value="{StaticResource Brush.Text.Primary}" />
            <Setter Property="Height" Value="32" />
            <Setter Property="MinWidth" Value="160" />
            <Setter Property="FontSize" Value="14" />
            <Setter Property="Cursor" Value="Hand" />
            <Setter Property="FocusVisualStyle" Value="{x:Null}" />
            <Setter Property="ScrollViewer.HorizontalScrollBarVisibility" Value="Disabled" />
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ComboBox">
                        <Grid SnapsToDevicePixels="True">
                            <Border x:Name="Bd" Background="{StaticResource Brush.Bg.Surface}" BorderBrush="{StaticResource Brush.Border.Default}" BorderThickness="1" CornerRadius="4" />
                            <ContentPresenter x:Name="ContentSite" IsHitTestVisible="False" Margin="12,0,32,0" VerticalAlignment="Center" HorizontalAlignment="Left" Content="{TemplateBinding SelectionBoxItem}" ContentTemplate="{TemplateBinding SelectionBoxItemTemplate}" ContentTemplateSelector="{TemplateBinding ItemTemplateSelector}" />
                            <ToggleButton x:Name="Toggle" Style="{StaticResource ComboBox.Toggle}" IsChecked="{Binding IsDropDownOpen, Mode=TwoWay, RelativeSource={RelativeSource TemplatedParent}}" />
                            <Popup x:Name="PART_Popup" Placement="Bottom" IsOpen="{TemplateBinding IsDropDownOpen}" AllowsTransparency="True" Focusable="False" PopupAnimation="None">
                                <Border Margin="0,4,0,0" Padding="4" Background="{StaticResource Brush.Bg.Surface}" BorderBrush="{StaticResource Brush.Border.Default}" BorderThickness="1" CornerRadius="6" MinWidth="{Binding ActualWidth, RelativeSource={RelativeSource TemplatedParent}}" MaxHeight="{TemplateBinding MaxDropDownHeight}">
                                    <ScrollViewer SnapsToDevicePixels="True">
                                        <StackPanel IsItemsHost="True" KeyboardNavigation.DirectionalNavigation="Contained" />
                                    </ScrollViewer>
                                </Border>
                            </Popup>
                        </Grid>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="Bd" Property="Background" Value="{StaticResource Brush.Bg.Hover}" />
                            </Trigger>
                            <Trigger Property="IsKeyboardFocusWithin" Value="True">
                                <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource Brush.Accent}" />
                            </Trigger>
                            <Trigger Property="IsDropDownOpen" Value="True">
                                <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource Brush.Accent}" />
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter Property="Opacity" Value="0.5" />
                                <Setter Property="Cursor" Value="Arrow" />
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
        <Style TargetType="ComboBoxItem">
            <Setter Property="Foreground" Value="{StaticResource Brush.Text.Primary}" />
            <Setter Property="Cursor" Value="Hand" />
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ComboBoxItem">
                        <Border x:Name="Bd" Background="Transparent" CornerRadius="4" Padding="10,6" SnapsToDevicePixels="True">
                            <ContentPresenter />
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsHighlighted" Value="True">
                                <Setter TargetName="Bd" Property="Background" Value="{StaticResource Brush.Bg.Hover}" />
                            </Trigger>
                            <Trigger Property="IsSelected" Value="True">
                                <Setter TargetName="Bd" Property="Background" Value="{StaticResource Brush.Bg.Pressed}" />
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="TextBox.Search" TargetType="TextBox">
            <Setter Property="Foreground" Value="{StaticResource Brush.Text.Primary}" />
            <Setter Property="CaretBrush" Value="{StaticResource Brush.Accent}" />
            <Setter Property="SelectionBrush" Value="{StaticResource Brush.Accent}" />
            <Setter Property="Height" Value="32" />
            <Setter Property="FontSize" Value="14" />
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="TextBox">
                        <Border x:Name="Bd" Background="{StaticResource Brush.Bg.Surface}" BorderBrush="{StaticResource Brush.Border.Default}" BorderThickness="1" CornerRadius="4" SnapsToDevicePixels="True">
                            <Grid Margin="10,0,30,0">
                                <Grid.ColumnDefinitions>
                                    <ColumnDefinition Width="Auto" />
                                    <ColumnDefinition Width="*" />
                                </Grid.ColumnDefinitions>
                                <TextBlock Style="{StaticResource Text.Icon}" FontSize="12" Text="&#xE721;" Foreground="{StaticResource Brush.Text.Tertiary}" Margin="0,0,8,0" />
                                <TextBlock x:Name="Placeholder" Grid.Column="1" Text="{Binding Tag, RelativeSource={RelativeSource TemplatedParent}}" Foreground="{StaticResource Brush.Text.Tertiary}" VerticalAlignment="Center" Visibility="Collapsed" IsHitTestVisible="False" />
                                <ScrollViewer x:Name="PART_ContentHost" Grid.Column="1" VerticalAlignment="Center" Focusable="False" HorizontalScrollBarVisibility="Hidden" VerticalScrollBarVisibility="Hidden" />
                            </Grid>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="Text" Value="">
                                <Setter TargetName="Placeholder" Property="Visibility" Value="Visible" />
                            </Trigger>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource Brush.Text.Tertiary}" />
                            </Trigger>
                            <Trigger Property="IsKeyboardFocused" Value="True">
                                <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource Brush.Accent}" />
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <Style x:Key="TextBox.Log" TargetType="TextBox">
            <Setter Property="Background" Value="{StaticResource Brush.Bg.Window}" />
            <Setter Property="Foreground" Value="{StaticResource Brush.Text.Secondary}" />
            <Setter Property="BorderThickness" Value="0" />
            <Setter Property="Padding" Value="12,8" />
            <Setter Property="FontFamily" Value="{StaticResource Font.Mono}" />
            <Setter Property="FontSize" Value="12" />
            <Setter Property="IsReadOnly" Value="True" />
            <Setter Property="TextWrapping" Value="Wrap" />
            <Setter Property="VerticalScrollBarVisibility" Value="Auto" />
            <Setter Property="SelectionBrush" Value="{StaticResource Brush.Accent}" />
        </Style>

        <Style TargetType="ToolTip">
            <Setter Property="Foreground" Value="{StaticResource Brush.Text.Primary}" />
            <Setter Property="FontSize" Value="12" />
            <Setter Property="MaxWidth" Value="440" />
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ToolTip">
                        <Border Background="{StaticResource Brush.Bg.Surface}" BorderBrush="{StaticResource Brush.Border.Default}" BorderThickness="1" CornerRadius="4" Padding="12,10">
                            <ContentPresenter>
                                <ContentPresenter.Resources>
                                    <Style TargetType="TextBlock">
                                        <Setter Property="TextWrapping" Value="Wrap" />
                                    </Style>
                                </ContentPresenter.Resources>
                            </ContentPresenter>
                        </Border>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Barra de rolagem fina (a padr&#x00E3;o &#x00E9; clara e grossa no tema escuro). -->
        <Style x:Key="ScrollBar.Thumb" TargetType="Thumb">
            <Setter Property="OverridesDefaultStyle" Value="True" />
            <Setter Property="IsTabStop" Value="False" />
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Thumb">
                        <Border x:Name="T" Background="{StaticResource Brush.Border.Default}" CornerRadius="3" />
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="T" Property="Background" Value="{StaticResource Brush.Text.Tertiary}" />
                            </Trigger>
                            <Trigger Property="IsDragging" Value="True">
                                <Setter TargetName="T" Property="Background" Value="{StaticResource Brush.Text.Secondary}" />
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
        <Style x:Key="ScrollBar.Page" TargetType="RepeatButton">
            <Setter Property="OverridesDefaultStyle" Value="True" />
            <Setter Property="Focusable" Value="False" />
            <Setter Property="IsTabStop" Value="False" />
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="RepeatButton">
                        <Border Background="Transparent" />
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
        <Style TargetType="ScrollBar">
            <Setter Property="OverridesDefaultStyle" Value="True" />
            <Setter Property="Background" Value="Transparent" />
            <Style.Triggers>
                <Trigger Property="Orientation" Value="Vertical">
                    <Setter Property="Width" Value="10" />
                    <Setter Property="MinWidth" Value="10" />
                    <Setter Property="Template">
                        <Setter.Value>
                            <ControlTemplate TargetType="ScrollBar">
                                <Grid Background="Transparent">
                                    <Track x:Name="PART_Track" IsDirectionReversed="True">
                                        <Track.DecreaseRepeatButton>
                                            <RepeatButton Style="{StaticResource ScrollBar.Page}" Command="ScrollBar.PageUpCommand" />
                                        </Track.DecreaseRepeatButton>
                                        <Track.Thumb>
                                            <Thumb Style="{StaticResource ScrollBar.Thumb}" Margin="2" />
                                        </Track.Thumb>
                                        <Track.IncreaseRepeatButton>
                                            <RepeatButton Style="{StaticResource ScrollBar.Page}" Command="ScrollBar.PageDownCommand" />
                                        </Track.IncreaseRepeatButton>
                                    </Track>
                                </Grid>
                            </ControlTemplate>
                        </Setter.Value>
                    </Setter>
                </Trigger>
                <Trigger Property="Orientation" Value="Horizontal">
                    <Setter Property="Height" Value="10" />
                    <Setter Property="MinHeight" Value="10" />
                    <Setter Property="Template">
                        <Setter.Value>
                            <ControlTemplate TargetType="ScrollBar">
                                <Grid Background="Transparent">
                                    <Track x:Name="PART_Track" IsDirectionReversed="False">
                                        <Track.DecreaseRepeatButton>
                                            <RepeatButton Style="{StaticResource ScrollBar.Page}" Command="ScrollBar.PageLeftCommand" />
                                        </Track.DecreaseRepeatButton>
                                        <Track.Thumb>
                                            <Thumb Style="{StaticResource ScrollBar.Thumb}" Margin="2" />
                                        </Track.Thumb>
                                        <Track.IncreaseRepeatButton>
                                            <RepeatButton Style="{StaticResource ScrollBar.Page}" Command="ScrollBar.PageRightCommand" />
                                        </Track.IncreaseRepeatButton>
                                    </Track>
                                </Grid>
                            </ControlTemplate>
                        </Setter.Value>
                    </Setter>
                </Trigger>
            </Style.Triggers>
        </Style>

        <Style x:Key="Progress.Thin" TargetType="ProgressBar">
            <Setter Property="Height" Value="2" />
            <Setter Property="Foreground" Value="{StaticResource Brush.Accent}" />
            <Setter Property="Background" Value="Transparent" />
            <Setter Property="BorderThickness" Value="0" />
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ProgressBar">
                        <Grid>
                            <Border x:Name="PART_Track" Background="{TemplateBinding Background}" />
                            <Border x:Name="PART_Indicator" Background="{TemplateBinding Foreground}" HorizontalAlignment="Left" />
                        </Grid>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Navega&#x00E7;&#x00E3;o lateral: ListBox ligado ao SelectedIndex do TabControl (o TabControl s&#x00F3; troca o conte&#x00FA;do). -->
        <Style x:Key="Nav.Item" TargetType="ListBoxItem">
            <Setter Property="Foreground" Value="{StaticResource Brush.Text.Secondary}" />
            <Setter Property="Padding" Value="12,0" />
            <Setter Property="Height" Value="36" />
            <Setter Property="Margin" Value="0,0,0,2" />
            <Setter Property="Cursor" Value="Hand" />
            <Setter Property="FocusVisualStyle" Value="{StaticResource FocusVisual.Accent}" />
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ListBoxItem">
                        <Border x:Name="Bd" Background="Transparent" CornerRadius="4" Padding="{TemplateBinding Padding}" SnapsToDevicePixels="True">
                            <Grid>
                                <Border x:Name="Pill" Width="3" Height="16" CornerRadius="1.5" Background="{StaticResource Brush.Accent}" HorizontalAlignment="Left" Margin="-12,0,0,0" Visibility="Collapsed" />
                                <ContentPresenter VerticalAlignment="Center" />
                            </Grid>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="Bd" Property="Background" Value="{StaticResource Brush.Bg.Hover}" />
                                <Setter Property="Foreground" Value="{StaticResource Brush.Text.Primary}" />
                            </Trigger>
                            <Trigger Property="IsSelected" Value="True">
                                <Setter TargetName="Bd" Property="Background" Value="{StaticResource Brush.Bg.Pressed}" />
                                <Setter TargetName="Pill" Property="Visibility" Value="Visible" />
                                <Setter Property="Foreground" Value="{StaticResource Brush.Text.Primary}" />
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
        <Style x:Key="Nav.List" TargetType="ListBox">
            <Setter Property="Background" Value="Transparent" />
            <Setter Property="BorderThickness" Value="0" />
            <Setter Property="ItemContainerStyle" Value="{StaticResource Nav.Item}" />
            <Setter Property="ScrollViewer.HorizontalScrollBarVisibility" Value="Disabled" />
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ListBox">
                        <ItemsPresenter />
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Obrigat&#x00F3;rio: o conte&#x00FA;do de cada aba herda Foreground do TabItem (preto no Aero2), n&#x00E3;o da Window. -->
        <Style TargetType="TabItem">
            <Setter Property="Foreground" Value="{StaticResource Brush.Text.Primary}" />
        </Style>
        <Style x:Key="Tab.ContentOnly" TargetType="TabControl">
            <Setter Property="Background" Value="Transparent" />
            <Setter Property="BorderThickness" Value="0" />
            <Setter Property="Padding" Value="0" />
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="TabControl">
                        <Grid>
                            <TabPanel IsItemsHost="True" Visibility="Collapsed" />
                            <ContentPresenter ContentSource="SelectedContent" />
                        </Grid>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- A barra de sele&#x00E7;&#x00E3;o s&#x00F3; existe nas p&#x00E1;ginas de lista (0 = Apps, 1 = Ajustes, 2 = Jogos). -->
        <Style x:Key="SelectionBar.Visibility" TargetType="DockPanel">
            <Setter Property="Visibility" Value="Visible" />
            <Style.Triggers>
                <DataTrigger Binding="{Binding SelectedIndex, ElementName=MainTabControl}" Value="3">
                    <Setter Property="Visibility" Value="Collapsed" />
                </DataTrigger>
                <DataTrigger Binding="{Binding SelectedIndex, ElementName=MainTabControl}" Value="4">
                    <Setter Property="Visibility" Value="Collapsed" />
                </DataTrigger>
                <DataTrigger Binding="{Binding SelectedIndex, ElementName=MainTabControl}" Value="5">
                    <Setter Property="Visibility" Value="Collapsed" />
                </DataTrigger>
            </Style.Triggers>
        </Style>

        <!-- Tabela de inicializa&#x00E7;&#x00E3;o. -->
        <Style x:Key="DataGrid.Clean" TargetType="DataGrid">
            <Setter Property="Background" Value="Transparent" />
            <Setter Property="Foreground" Value="{StaticResource Brush.Text.Primary}" />
            <Setter Property="BorderThickness" Value="0" />
            <Setter Property="RowBackground" Value="Transparent" />
            <Setter Property="AlternatingRowBackground" Value="Transparent" />
            <Setter Property="GridLinesVisibility" Value="Horizontal" />
            <Setter Property="HorizontalGridLinesBrush" Value="{StaticResource Brush.Border.Subtle}" />
            <Setter Property="HeadersVisibility" Value="Column" />
            <Setter Property="RowHeight" Value="36" />
            <Setter Property="CanUserResizeRows" Value="False" />
            <Setter Property="SelectionMode" Value="Single" />
            <Setter Property="SelectionUnit" Value="FullRow" />
            <Setter Property="AutoGenerateColumns" Value="False" />
            <Setter Property="IsReadOnly" Value="True" />
            <Setter Property="FontSize" Value="14" />
        </Style>
        <Style TargetType="DataGridColumnHeader">
            <Setter Property="Foreground" Value="{StaticResource Brush.Text.Secondary}" />
            <Setter Property="FontSize" Value="12" />
            <Setter Property="FontWeight" Value="SemiBold" />
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="DataGridColumnHeader">
                        <Border Background="Transparent" BorderBrush="{StaticResource Brush.Border.Default}" BorderThickness="0,0,0,1" Padding="12,8">
                            <ContentPresenter VerticalAlignment="Center" />
                        </Border>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>
        <Style TargetType="DataGridRow">
            <Setter Property="Background" Value="Transparent" />
            <Style.Triggers>
                <Trigger Property="IsMouseOver" Value="True">
                    <Setter Property="Background" Value="{StaticResource Brush.Bg.Hover}" />
                </Trigger>
                <Trigger Property="IsSelected" Value="True">
                    <Setter Property="Background" Value="{StaticResource Brush.Bg.Pressed}" />
                </Trigger>
            </Style.Triggers>
        </Style>
        <Style TargetType="DataGridCell">
            <Setter Property="Padding" Value="12,0" />
            <Setter Property="FocusVisualStyle" Value="{x:Null}" />
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="DataGridCell">
                        <Border Background="Transparent" Padding="{TemplateBinding Padding}">
                            <ContentPresenter VerticalAlignment="Center" />
                        </Border>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
            <Style.Triggers>
                <Trigger Property="IsSelected" Value="True">
                    <Setter Property="Foreground" Value="{StaticResource Brush.Text.Primary}" />
                </Trigger>
            </Style.Triggers>
        </Style>
        <Style x:Key="Cell.Text" TargetType="TextBlock">
            <Setter Property="TextTrimming" Value="CharacterEllipsis" />
            <Setter Property="VerticalAlignment" Value="Center" />
        </Style>
        <Style x:Key="Cell.Status" TargetType="TextBlock" BasedOn="{StaticResource Cell.Text}">
            <Style.Triggers>
                <DataTrigger Binding="{Binding Enabled}" Value="False">
                    <Setter Property="Foreground" Value="{StaticResource Brush.Text.Tertiary}" />
                </DataTrigger>
            </Style.Triggers>
        </Style>
        <Style x:Key="Cell.Meta" TargetType="TextBlock" BasedOn="{StaticResource Cell.Text}">
            <Setter Property="FontSize" Value="12" />
            <Setter Property="Foreground" Value="{StaticResource Brush.Text.Secondary}" />
        </Style>
        <Style x:Key="Cell.Command" TargetType="TextBlock" BasedOn="{StaticResource Cell.Meta}">
            <Setter Property="FontFamily" Value="{StaticResource Font.Mono}" />
            <Setter Property="Foreground" Value="{StaticResource Brush.Text.Tertiary}" />
            <Setter Property="ToolTip" Value="{Binding Command}" />
        </Style>
    </Window.Resources>

    <Grid>
        <Grid.RowDefinitions>
            <RowDefinition Height="*" />
            <RowDefinition Height="Auto" />
        </Grid.RowDefinitions>
        <Grid.ColumnDefinitions>
            <ColumnDefinition Width="232" />
            <ColumnDefinition Width="*" />
        </Grid.ColumnDefinitions>

        <!-- Navega&#x00E7;&#x00E3;o lateral: identidade, busca, se&#x00E7;&#x00F5;es e resumo de hardware. -->
        <Border Grid.Row="0" Grid.Column="0" Background="{StaticResource Brush.Bg.Rail}" BorderBrush="{StaticResource Brush.Border.Subtle}" BorderThickness="0,0,1,0">
            <DockPanel Margin="12,20,12,16">
                <StackPanel DockPanel.Dock="Top" Margin="8,0,8,20">
                    <TextBlock Text="OptiKit" Style="{StaticResource Text.Title}" />
                    <Border x:Name="BadgeDryRun" Visibility="Collapsed" HorizontalAlignment="Left" Margin="0,8,0,0" Padding="8,2" CornerRadius="4" BorderThickness="1" BorderBrush="{StaticResource Brush.Warning}">
                        <TextBlock Text="Modo simula&#x00E7;&#x00E3;o" Style="{StaticResource Text.Caption}" Foreground="{StaticResource Brush.Warning}" />
                    </Border>
                    <Border x:Name="BadgeUpdate" Visibility="Collapsed" HorizontalAlignment="Left" Margin="0,8,0,0" Background="Transparent" Cursor="Hand" ToolTip="Abrir a p&#x00E1;gina de releases do OptiKit">
                        <TextBlock x:Name="TxtUpdateBadge" Text="Nova vers&#x00E3;o dispon&#x00ED;vel" Style="{StaticResource Text.Caption}" Foreground="{StaticResource Brush.Accent}" TextDecorations="Underline" />
                    </Border>
                </StackPanel>

                <Grid DockPanel.Dock="Top" Margin="0,0,0,16">
                    <TextBox x:Name="TxtSearchBox" Style="{StaticResource TextBox.Search}" Tag="Buscar apps e ajustes" AutomationProperties.Name="Buscar apps e ajustes" ToolTip="Filtra aplicativos, ajustes e otimiza&#x00E7;&#x00F5;es de jogos" />
                    <Button x:Name="BtnClearSearch" Style="{StaticResource Button.SearchClear}" Content="&#xE711;" HorizontalAlignment="Right" Margin="0,0,2,0" ToolTip="Limpar busca" AutomationProperties.Name="Limpar busca" />
                </Grid>

                <TextBlock x:Name="TxtHardwareSummary" DockPanel.Dock="Bottom" Style="{StaticResource Text.Meta}" TextWrapping="Wrap" Margin="8,16,8,0" Text="Detectando hardware..." />

                <ListBox x:Name="NavList" Style="{StaticResource Nav.List}" SelectedIndex="{Binding SelectedIndex, ElementName=MainTabControl, Mode=TwoWay}">
                    <ListBoxItem AutomationProperties.Name="Instalar apps">
                        <StackPanel Orientation="Horizontal">
                            <TextBlock Style="{StaticResource Nav.Icon}" Text="&#xE71D;" />
                            <TextBlock Text="Instalar apps" VerticalAlignment="Center" />
                        </StackPanel>
                    </ListBoxItem>
                    <ListBoxItem AutomationProperties.Name="Ajustes do Windows">
                        <StackPanel Orientation="Horizontal">
                            <TextBlock Style="{StaticResource Nav.Icon}" Text="&#xE713;" />
                            <TextBlock Text="Ajustes do Windows" VerticalAlignment="Center" />
                        </StackPanel>
                    </ListBoxItem>
                    <ListBoxItem AutomationProperties.Name="Jogos">
                        <StackPanel Orientation="Horizontal">
                            <TextBlock Style="{StaticResource Nav.Icon}" Text="&#xE7FC;" />
                            <TextBlock Text="Jogos" VerticalAlignment="Center" />
                        </StackPanel>
                    </ListBoxItem>
                    <ListBoxItem AutomationProperties.Name="Diagn&#x00F3;stico">
                        <StackPanel Orientation="Horizontal">
                            <TextBlock Style="{StaticResource Nav.Icon}" Text="&#xE9D9;" />
                            <TextBlock Text="Diagn&#x00F3;stico" VerticalAlignment="Center" />
                        </StackPanel>
                    </ListBoxItem>
                    <ListBoxItem AutomationProperties.Name="Inicializa&#x00E7;&#x00E3;o">
                        <StackPanel Orientation="Horizontal">
                            <TextBlock Style="{StaticResource Nav.Icon}" Text="&#xE7E8;" />
                            <TextBlock Text="Inicializa&#x00E7;&#x00E3;o" VerticalAlignment="Center" />
                        </StackPanel>
                    </ListBoxItem>
                    <ListBoxItem AutomationProperties.Name="Manuten&#x00E7;&#x00E3;o">
                        <StackPanel Orientation="Horizontal">
                            <TextBlock Style="{StaticResource Nav.Icon}" Text="&#xE90F;" />
                            <TextBlock Text="Manuten&#x00E7;&#x00E3;o" VerticalAlignment="Center" />
                        </StackPanel>
                    </ListBoxItem>
                </ListBox>
            </DockPanel>
        </Border>

        <TabControl x:Name="MainTabControl" Grid.Row="0" Grid.Column="1" Style="{StaticResource Tab.ContentOnly}">
            <!-- 0. Instalar apps -->
            <TabItem Header="Instalar apps">
                <Grid Margin="32,24,0,0">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto" />
                        <RowDefinition Height="*" />
                    </Grid.RowDefinitions>
                    <DockPanel Grid.Row="0" Margin="0,0,32,16">
                        <Button x:Name="BtnUncheckAllApps" DockPanel.Dock="Right" Style="{StaticResource Button.Subtle}" Content="Desmarcar apps" VerticalAlignment="Bottom" />
                        <StackPanel>
                            <TextBlock Text="Instalar apps" Style="{StaticResource Text.Title}" />
                            <TextBlock Text="Instala&#x00E7;&#x00E3;o silenciosa via winget. Passe o mouse em um app para ver o ID do pacote." Style="{StaticResource Text.Caption}" TextWrapping="Wrap" Margin="0,4,0,0" />
                        </StackPanel>
                    </DockPanel>
                    <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                        <StackPanel Margin="0,0,24,32">
                            <TextBlock x:Name="TxtAppsEmpty" Visibility="Collapsed" Style="{StaticResource Text.Caption}" Margin="0,8,0,0" />
                            <StackPanel x:Name="AppsCategoriesHost" />
                        </StackPanel>
                    </ScrollViewer>
                </Grid>
            </TabItem>

            <!-- 1. Ajustes do Windows -->
            <TabItem Header="Ajustes do Windows">
                <Grid Margin="32,24,0,0">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto" />
                        <RowDefinition Height="Auto" />
                        <RowDefinition Height="*" />
                    </Grid.RowDefinitions>
                    <DockPanel Grid.Row="0" Margin="0,0,32,12">
                        <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" VerticalAlignment="Bottom">
                            <Button x:Name="BtnRefreshState" Style="{StaticResource Button.Subtle}" Content="Atualizar estado" />
                            <Button x:Name="BtnUncheckAllTweaks" Style="{StaticResource Button.Subtle}" Content="Desmarcar ajustes" Margin="4,0,0,0" />
                        </StackPanel>
                        <StackPanel>
                            <TextBlock Text="Ajustes do Windows" Style="{StaticResource Text.Title}" />
                            <TextBlock Text="Tudo &#x00E9; salvo antes de aplicar e pode ser revertido. Passe o mouse em um ajuste para ver a justificativa t&#x00E9;cnica." Style="{StaticResource Text.Caption}" TextWrapping="Wrap" Margin="0,4,0,0" />
                        </StackPanel>
                    </DockPanel>
                    <DockPanel Grid.Row="1" Margin="0,0,32,12" LastChildFill="True">
                        <TextBlock x:Name="TxtTweakCount" DockPanel.Dock="Right" Style="{StaticResource Text.Caption}" VerticalAlignment="Center" Margin="12,0,0,0" />
                        <WrapPanel Orientation="Horizontal">
                            <ComboBox x:Name="CmbTweakSort" Width="200" Margin="0,0,8,6" ToolTip="Organiza os ajustes por categoria, impacto, risco, rein&#x00ED;cio ou estado" AutomationProperties.Name="Organizar ajustes" />
                            <ComboBox x:Name="CmbTweakImpact" Width="160" Margin="0,0,8,6" ToolTip="Mostra apenas ajustes com o impacto selecionado" AutomationProperties.Name="Filtrar por impacto" />
                            <ComboBox x:Name="CmbTweakRisk" Width="160" Margin="0,0,8,6" ToolTip="Mostra apenas ajustes com o risco selecionado" AutomationProperties.Name="Filtrar por risco" />
                            <ComboBox x:Name="CmbTweakStatus" Width="170" Margin="0,0,8,6" ToolTip="Mostra apenas ajustes aplicados, n&#x00E3;o aplicados ou desconhecidos" AutomationProperties.Name="Filtrar por estado" />
                            <Button x:Name="BtnClearTweakFilters" Style="{StaticResource Button.Subtle}" Content="Limpar filtros" Visibility="Collapsed" Margin="0,0,0,6" ToolTip="Volta a mostrar todos os ajustes" AutomationProperties.Name="Limpar filtros de ajustes" />
                        </WrapPanel>
                    </DockPanel>
                    <ScrollViewer Grid.Row="2" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                        <StackPanel Margin="0,0,24,32">
                            <TextBlock x:Name="TxtTweaksEmpty" Visibility="Collapsed" Style="{StaticResource Text.Caption}" Margin="0,8,0,0" />
                            <StackPanel x:Name="TweaksCategoriesHost" />
                        </StackPanel>
                    </ScrollViewer>
                </Grid>
            </TabItem>

            <!-- 2. Jogos -->
            <TabItem Header="Jogos">
                <Grid Margin="32,24,0,0">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto" />
                        <RowDefinition Height="*" />
                    </Grid.RowDefinitions>
                    <StackPanel Grid.Row="0" Margin="0,0,32,16">
                        <TextBlock Text="Jogos" Style="{StaticResource Text.Title}" />
                        <TextBlock Text="Otimiza&#x00E7;&#x00F5;es por jogo, compat&#x00ED;veis com o anti-cheat de cada t&#x00ED;tulo. Selecione o execut&#x00E1;vel quando ele n&#x00E3;o for detectado." Style="{StaticResource Text.Caption}" TextWrapping="Wrap" Margin="0,4,0,0" />
                    </StackPanel>
                    <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                        <StackPanel Margin="0,0,24,32">
                            <TextBlock x:Name="TxtGamesEmpty" Visibility="Collapsed" Style="{StaticResource Text.Caption}" Margin="0,8,0,0" />
                            <StackPanel x:Name="GameProfilesHost" />
                        </StackPanel>
                    </ScrollViewer>
                </Grid>
            </TabItem>

            <!-- 3. Diagn&#x00F3;stico -->
            <TabItem Header="Diagn&#x00F3;stico">
                <Grid Margin="32,24,0,0">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto" />
                        <RowDefinition Height="*" />
                    </Grid.RowDefinitions>
                    <DockPanel Grid.Row="0" Margin="0,0,32,16">
                        <Button x:Name="BtnRefreshDiagnostics" DockPanel.Dock="Right" Content="Executar novamente" VerticalAlignment="Bottom" />
                        <StackPanel>
                            <TextBlock Text="Diagn&#x00F3;stico" Style="{StaticResource Text.Title}" />
                            <TextBlock x:Name="TxtDiagnosticsSummary" Text="Somente leitura. Aguardando a verifica&#x00E7;&#x00E3;o." Style="{StaticResource Text.Caption}" TextWrapping="Wrap" Margin="0,4,0,0" />
                        </StackPanel>
                    </DockPanel>
                    <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                        <StackPanel x:Name="DiagnosticsHost" Margin="0,0,24,32" />
                    </ScrollViewer>
                </Grid>
            </TabItem>

            <!-- 4. Inicializa&#x00E7;&#x00E3;o -->
            <TabItem Header="Inicializa&#x00E7;&#x00E3;o">
                <Grid Margin="32,24,32,0">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto" />
                        <RowDefinition Height="*" />
                    </Grid.RowDefinitions>
                    <DockPanel Grid.Row="0" Margin="0,0,0,16">
                        <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" VerticalAlignment="Bottom">
                            <Button x:Name="BtnRefreshStartup" Style="{StaticResource Button.Subtle}" Content="Recarregar" />
                            <Button x:Name="BtnDisableStartup" Content="Desativar" Margin="8,0,0,0" />
                            <Button x:Name="BtnEnableStartup" Content="Ativar" Margin="8,0,0,0" />
                        </StackPanel>
                        <StackPanel>
                            <TextBlock Text="Inicializa&#x00E7;&#x00E3;o" Style="{StaticResource Text.Title}" />
                            <TextBlock Text="Programas que iniciam com o Windows. Usa o mesmo registro do Gerenciador de Tarefas." Style="{StaticResource Text.Caption}" TextWrapping="Wrap" Margin="0,4,0,0" />
                        </StackPanel>
                    </DockPanel>
                    <DataGrid x:Name="GridStartupItems" Grid.Row="1" Style="{StaticResource DataGrid.Clean}" Margin="0,0,0,24">
                        <DataGrid.Columns>
                            <DataGridTextColumn Header="Estado" Binding="{Binding StatusText}" Width="110" ElementStyle="{StaticResource Cell.Status}" />
                            <DataGridTextColumn Header="Programa" Binding="{Binding Name}" Width="200" ElementStyle="{StaticResource Cell.Text}" />
                            <DataGridTextColumn Header="Escopo" Binding="{Binding Scope}" Width="180" ElementStyle="{StaticResource Cell.Meta}" />
                            <DataGridTextColumn Header="Comando" Binding="{Binding Command}" Width="*" ElementStyle="{StaticResource Cell.Command}" />
                        </DataGrid.Columns>
                    </DataGrid>
                </Grid>
            </TabItem>

            <!-- 5. Manuten&#x00E7;&#x00E3;o -->
            <TabItem Header="Manuten&#x00E7;&#x00E3;o">
                <Grid Margin="32,24,0,0">
                    <Grid.RowDefinitions>
                        <RowDefinition Height="Auto" />
                        <RowDefinition Height="*" />
                    </Grid.RowDefinitions>
                    <StackPanel Grid.Row="0" Margin="0,0,32,0">
                        <TextBlock Text="Manuten&#x00E7;&#x00E3;o" Style="{StaticResource Text.Title}" />
                        <TextBlock Text="Reparo, limpeza, rede e revers&#x00E3;o. Opera&#x00E7;&#x00F5;es longas rodam em segundo plano e aparecem no log." Style="{StaticResource Text.Caption}" TextWrapping="Wrap" Margin="0,4,0,0" />
                    </StackPanel>
                    <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                        <StackPanel Margin="0,0,24,32">
                            <TextBlock Text="Reparo do sistema" Style="{StaticResource Section.Header}" />
                            <DockPanel Style="{StaticResource Action.Row}">
                                <StackPanel DockPanel.Dock="Right" Style="{StaticResource Action.Buttons}">
                                    <Button x:Name="BtnCancelMaintenance" Style="{StaticResource Button.Subtle}" Content="Cancelar" IsEnabled="False" Margin="0,0,8,0" />
                                    <Button x:Name="BtnRunSfcDism" Content="Executar" />
                                </StackPanel>
                                <StackPanel Style="{StaticResource Action.Text}">
                                    <TextBlock Text="Reparar arquivos do sistema" />
                                    <TextBlock Text="DISM /RestoreHealth seguido de SFC /scannow. Pode levar v&#x00E1;rios minutos." Style="{StaticResource Text.Caption}" TextWrapping="Wrap" Margin="0,2,0,0" />
                                </StackPanel>
                            </DockPanel>
                            <Border Style="{StaticResource Divider}" />
                            <DockPanel Style="{StaticResource Action.Row}">
                                <StackPanel DockPanel.Dock="Right" Style="{StaticResource Action.Buttons}">
                                    <Button x:Name="BtnResetNetwork" Content="Redefinir" />
                                </StackPanel>
                                <StackPanel Style="{StaticResource Action.Text}">
                                    <TextBlock Text="Redefinir rede" />
                                    <TextBlock Text="Winsock, pilha TCP/IP e cache DNS. Requer reinicializa&#x00E7;&#x00E3;o." Style="{StaticResource Text.Caption}" TextWrapping="Wrap" Margin="0,2,0,0" />
                                </StackPanel>
                            </DockPanel>

                            <TextBlock Text="Limpeza" Style="{StaticResource Section.Header}" />
                            <DockPanel Style="{StaticResource Action.Row}">
                                <StackPanel DockPanel.Dock="Right" Style="{StaticResource Action.Buttons}">
                                    <Button x:Name="BtnClearTemp" Content="Limpar" />
                                </StackPanel>
                                <StackPanel Style="{StaticResource Action.Text}">
                                    <TextBlock Text="Arquivos tempor&#x00E1;rios" />
                                    <TextBlock Text="Pastas %TEMP% do usu&#x00E1;rio e Windows\Temp. Arquivos em uso s&#x00E3;o ignorados." Style="{StaticResource Text.Caption}" TextWrapping="Wrap" Margin="0,2,0,0" />
                                </StackPanel>
                            </DockPanel>
                            <Border Style="{StaticResource Divider}" />
                            <DockPanel Style="{StaticResource Action.Row}">
                                <StackPanel DockPanel.Dock="Right" Style="{StaticResource Action.Buttons}">
                                    <Button x:Name="BtnAdvancedCleanup" Content="Limpar" />
                                </StackPanel>
                                <StackPanel Style="{StaticResource Action.Text}">
                                    <TextBlock Text="Limpeza avan&#x00E7;ada" />
                                    <TextBlock Text="Cache do Windows Update e do Delivery Optimization, Lixeira, Prefetch e Component Store. Pode levar v&#x00E1;rios minutos." Style="{StaticResource Text.Caption}" TextWrapping="Wrap" Margin="0,2,0,0" />
                                </StackPanel>
                            </DockPanel>

                            <TextBlock Text="Rede e atualiza&#x00E7;&#x00F5;es" Style="{StaticResource Section.Header}" />
                            <DockPanel Style="{StaticResource Action.Row}">
                                <StackPanel DockPanel.Dock="Right" Style="{StaticResource Action.Buttons}">
                                    <ComboBox x:Name="CmbDohProvider" Width="220" Margin="0,0,8,0" />
                                    <Button x:Name="BtnUndoDoh" Style="{StaticResource Button.Subtle}" Content="Reverter" Margin="0,0,8,0" />
                                    <Button x:Name="BtnApplyDoh" Content="Aplicar" />
                                </StackPanel>
                                <StackPanel Style="{StaticResource Action.Text}">
                                    <TextBlock Text="DNS over HTTPS" />
                                    <TextBlock Text="Criptografa as consultas DNS dos adaptadores ativos. Requer Windows 11." Style="{StaticResource Text.Caption}" TextWrapping="Wrap" Margin="0,2,0,0" />
                                </StackPanel>
                            </DockPanel>
                            <Border Style="{StaticResource Divider}" />
                            <DockPanel Style="{StaticResource Action.Row}">
                                <StackPanel DockPanel.Dock="Right" Style="{StaticResource Action.Buttons}">
                                    <Button x:Name="BtnWingetUpgrade" Content="Atualizar" />
                                </StackPanel>
                                <StackPanel Style="{StaticResource Action.Text}">
                                    <TextBlock Text="Atualizar aplicativos" />
                                    <TextBlock Text="Atualiza todos os apps gerenciados pelo winget. Alguns podem pedir reinicializa&#x00E7;&#x00E3;o." Style="{StaticResource Text.Caption}" TextWrapping="Wrap" Margin="0,2,0,0" />
                                </StackPanel>
                            </DockPanel>

                            <TextBlock Text="Hist&#x00F3;rico e revers&#x00E3;o" Style="{StaticResource Section.Header}" />
                            <DockPanel Style="{StaticResource Action.Row}">
                                <StackPanel DockPanel.Dock="Right" Style="{StaticResource Action.Buttons}">
                                    <Button x:Name="BtnViewApplied" Content="Ver altera&#x00E7;&#x00F5;es" />
                                </StackPanel>
                                <StackPanel Style="{StaticResource Action.Text}">
                                    <TextBlock Text="Altera&#x00E7;&#x00F5;es aplicadas" />
                                    <TextBlock Text="Ajustes ativos nesta m&#x00E1;quina e o que est&#x00E1; registrado para revers&#x00E3;o." Style="{StaticResource Text.Caption}" TextWrapping="Wrap" Margin="0,2,0,0" />
                                </StackPanel>
                            </DockPanel>
                            <Border Style="{StaticResource Divider}" />
                            <DockPanel Style="{StaticResource Action.Row}">
                                <StackPanel DockPanel.Dock="Right" Style="{StaticResource Action.Buttons}">
                                    <Button x:Name="BtnUndoAll" Style="{StaticResource Button.Danger}" Content="Reverter tudo" />
                                </StackPanel>
                                <StackPanel Style="{StaticResource Action.Text}">
                                    <TextBlock Text="Reverter tudo" />
                                    <TextBlock Text="Desfaz todas as altera&#x00E7;&#x00F5;es registradas pelo OptiKit: ajustes, jogos, energia, USB, DNS e Windows Update." Style="{StaticResource Text.Caption}" TextWrapping="Wrap" Margin="0,2,0,0" />
                                </StackPanel>
                            </DockPanel>

                            <TextBlock Text="Perfis e relat&#x00F3;rios" Style="{StaticResource Section.Header}" />
                            <DockPanel Style="{StaticResource Action.Row}">
                                <StackPanel DockPanel.Dock="Right" Style="{StaticResource Action.Buttons}">
                                    <Button x:Name="BtnImportProfile" Content="Importar" Margin="0,0,8,0" />
                                    <Button x:Name="BtnExportProfile" Content="Exportar" />
                                </StackPanel>
                                <StackPanel Style="{StaticResource Action.Text}">
                                    <TextBlock Text="Perfil de sele&#x00E7;&#x00E3;o" />
                                    <TextBlock Text="Salva ou carrega os itens marcados em um arquivo JSON." Style="{StaticResource Text.Caption}" TextWrapping="Wrap" Margin="0,2,0,0" />
                                </StackPanel>
                            </DockPanel>
                            <Border Style="{StaticResource Divider}" />
                            <DockPanel Style="{StaticResource Action.Row}">
                                <StackPanel DockPanel.Dock="Right" Style="{StaticResource Action.Buttons}">
                                    <Button x:Name="BtnExportReport" Content="Exportar" />
                                </StackPanel>
                                <StackPanel Style="{StaticResource Action.Text}">
                                    <TextBlock Text="Relat&#x00F3;rio da sess&#x00E3;o" />
                                    <TextBlock Text="HTML com hardware, diagn&#x00F3;stico, estados capturados e log." Style="{StaticResource Text.Caption}" TextWrapping="Wrap" Margin="0,2,0,0" />
                                </StackPanel>
                            </DockPanel>
                            <Border Style="{StaticResource Divider}" />
                            <DockPanel Style="{StaticResource Action.Row}">
                                <StackPanel DockPanel.Dock="Right" Style="{StaticResource Action.Buttons}">
                                    <Button x:Name="BtnOpenBackupsDir" Content="Abrir pasta" />
                                </StackPanel>
                                <StackPanel Style="{StaticResource Action.Text}">
                                    <TextBlock Text="Pasta de dados" />
                                    <TextBlock Text="Logs, backups .reg e state.json do OptiKit." Style="{StaticResource Text.Caption}" TextWrapping="Wrap" Margin="0,2,0,0" />
                                </StackPanel>
                            </DockPanel>
                        </StackPanel>
                    </ScrollViewer>
                </Grid>
            </TabItem>
        </TabControl>

        <!-- Rodap&#x00E9;: progresso, log recolh&#x00ED;vel, status e a&#x00E7;&#x00F5;es de sele&#x00E7;&#x00E3;o. -->
        <Border Grid.Row="1" Grid.ColumnSpan="2" Background="{StaticResource Brush.Bg.Rail}" BorderBrush="{StaticResource Brush.Border.Subtle}" BorderThickness="0,1,0,0">
            <Grid>
                <Grid.RowDefinitions>
                    <RowDefinition Height="Auto" />
                    <RowDefinition Height="Auto" />
                    <RowDefinition Height="Auto" />
                </Grid.RowDefinitions>
                <ProgressBar x:Name="MainProgressBar" Grid.Row="0" Style="{StaticResource Progress.Thin}" Minimum="0" Maximum="100" Value="0" Visibility="Hidden" />
                <Border x:Name="LogPanel" Grid.Row="1" Height="168" Visibility="Collapsed" BorderBrush="{StaticResource Brush.Border.Subtle}" BorderThickness="0,0,0,1">
                    <TextBox x:Name="TxtConsoleOutput" Style="{StaticResource TextBox.Log}" />
                </Border>
                <DockPanel Grid.Row="2" Margin="12,10,16,10" LastChildFill="True">
                    <!-- Ordem de dock importa: o que vem primeiro recebe espa&#x00E7;o primeiro. Aplicar nunca pode ser cortado. -->
                    <DockPanel x:Name="SelectionBar" DockPanel.Dock="Right" LastChildFill="False" Style="{StaticResource SelectionBar.Visibility}">
                        <Button x:Name="BtnApplySelected" DockPanel.Dock="Right" Style="{StaticResource Button.Primary}" Content="Aplicar selecionados" Margin="8,0,0,0" />
                        <Button x:Name="BtnUndoSelected" DockPanel.Dock="Right" Content="Reverter selecionados" Margin="8,0,0,0" />
                        <Button x:Name="BtnClearSelection" DockPanel.Dock="Right" Style="{StaticResource Button.Subtle}" Content="Limpar" Margin="4,0,0,0" />
                        <TextBlock x:Name="TxtSelectionCounter" DockPanel.Dock="Right" Text="Nenhum item selecionado" Style="{StaticResource Text.Caption}" VerticalAlignment="Center" Margin="12,0,0,0" />
                        <ComboBox x:Name="CmbPresets" DockPanel.Dock="Right" Width="200" ToolTip="Presets marcam um conjunto recomendado de itens" />
                    </DockPanel>
                    <Button x:Name="BtnToggleLog" DockPanel.Dock="Left" Style="{StaticResource Button.Subtle}" Content="Log" ToolTip="Mostrar ou ocultar o log da sess&#x00E3;o" Margin="0,0,8,0" />
                    <TextBlock x:Name="TxtStatusMessage" Text="Pronto." Style="{StaticResource Text.Caption}" VerticalAlignment="Center" TextTrimming="CharacterEllipsis" Margin="0,0,16,0" />
                </DockPanel>
            </Grid>
        </Border>
    </Grid>
</Window>
'@

# ============================================================================
# Module: src/windows/core/logger.ps1
# ============================================================================
# Sistema de logs, estado de execu--o e ponto -nico de muta--o (DryRun / Auditoria)

if (-not $script:OptiKit) {
    $defaultRoot = Join-Path $env:ProgramData 'optikit'
    $script:OptiKit = @{
        DataRoot      = $defaultRoot
        LogsDir       = Join-Path $defaultRoot 'logs'
        BackupsDir    = Join-Path $defaultRoot 'backups'
        StateFile     = Join-Path $defaultRoot 'state.json'
        LogFile       = $null
        DryRun        = $false
        SessionId     = (Get-Date -Format 'yyyy-MM-dd_HH-mm-ss')
        SessionDir    = $null
        SyncHash      = $null
        LogHistory    = New-Object 'System.Collections.Generic.List[string]'
        CancelRequest = $false
        ConsoleOutput = $false
        SessionCounts = @{ Applied = 0; Skipped = 0; Failed = 0 }
    }
}

function Initialize-OptiKitEnvironment {
    [CmdletBinding()]
    param(
        [string]$DataRoot,
        [switch]$DryRun,
        [hashtable]$SyncHash
    )

    if ($DataRoot) {
        $script:OptiKit.DataRoot   = $DataRoot
        $script:OptiKit.LogsDir    = Join-Path $DataRoot 'logs'
        $script:OptiKit.BackupsDir = Join-Path $DataRoot 'backups'
        $script:OptiKit.StateFile  = Join-Path $DataRoot 'state.json'
    }

    $script:OptiKit.SessionCounts = @{ Applied = 0; Skipped = 0; Failed = 0 }

    if ($PSBoundParameters.ContainsKey('DryRun')) {
        $script:OptiKit.DryRun = [bool]$DryRun
    }

    if ($SyncHash) {
        $script:OptiKit.SyncHash = $SyncHash
    }

    try {
        if (-not (Test-Path -LiteralPath $script:OptiKit.LogsDir)) {
            New-Item -Path $script:OptiKit.LogsDir -ItemType Directory -Force | Out-Null
        }
        if (-not (Test-Path -LiteralPath $script:OptiKit.BackupsDir)) {
            New-Item -Path $script:OptiKit.BackupsDir -ItemType Directory -Force | Out-Null
        }
    }
    catch {
        $fallbackRoot = Join-Path $env:TEMP 'optikit'
        $script:OptiKit.DataRoot   = $fallbackRoot
        $script:OptiKit.LogsDir    = Join-Path $fallbackRoot 'logs'
        $script:OptiKit.BackupsDir = Join-Path $fallbackRoot 'backups'
        $script:OptiKit.StateFile  = Join-Path $fallbackRoot 'state.json'
        New-Item -Path $script:OptiKit.LogsDir -ItemType Directory -Force | Out-Null
        New-Item -Path $script:OptiKit.BackupsDir -ItemType Directory -Force | Out-Null
    }

    if (-not $script:OptiKit.SessionId) {
        $script:OptiKit.SessionId = Get-Date -Format 'yyyy-MM-dd_HH-mm-ss'
    }
    $script:OptiKit.LogFile = Join-Path $script:OptiKit.LogsDir ("optikit_{0}.log" -f $script:OptiKit.SessionId)
    return $script:OptiKit
}

function Write-OptimizerLog {
    [CmdletBinding()]
    param(
        [ValidateSet('INFO', 'OK', 'WARN', 'ERROR', 'DRYRUN')]
        [string]$Level = 'INFO',

        [Parameter(Mandatory = $true)]
        [AllowEmptyString()]
        [string]$Message
    )

    $timestamp = Get-Date -Format 'HH:mm:ss'
    $line = "[{0}] [{1}] {2}" -f $timestamp, $Level, $Message

    if ($script:OptiKit -and $null -ne $script:OptiKit.LogHistory) {
        [void]$script:OptiKit.LogHistory.Add($line)
    }

    if ($script:OptiKit -and $script:OptiKit.LogFile) {
        try {
            $utf8Bom = New-Object System.Text.UTF8Encoding($true)
            [System.IO.File]::AppendAllText($script:OptiKit.LogFile, ($line + [Environment]::NewLine), $utf8Bom)
        }
        catch {
            Write-Verbose ("Falha ao gravar arquivo de log: {0}" -f $_.Exception.Message)
        }
    }

    if ($script:OptiKit -and $script:OptiKit.SyncHash) {
        $sync = $script:OptiKit.SyncHash
        if ($sync.LogQueue) {
            $entry = [pscustomobject]@{
                Timestamp = $timestamp
                Level     = $Level
                Message   = $Message
                Formatted = $line
            }
            $sync.LogQueue.Enqueue($entry)
        }
        $sync.StatusText = $Message
    }

    if ($script:OptiKit -and $script:OptiKit.ConsoleOutput) {
        Write-Host $line
    }
}

function Invoke-Mutation {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Description,

        [Parameter(Mandatory = $true)]
        [scriptblock]$Action
    )

    if ($script:OptiKit -and $script:OptiKit.DryRun) {
        Write-OptimizerLog -Level DRYRUN -Message $Description
        return $true
    }

    try {
        & $Action
        Write-OptimizerLog -Level OK -Message $Description
        return $true
    }
    catch {
        Write-OptimizerLog -Level WARN -Message ("{0} $([char]0x2014) {1}" -f $Description, $_.Exception.Message)
        throw
    }
}

# ============================================================================
# Module: src/windows/core/backup.ps1
# ============================================================================
# Ponto de Restaura--o, exporta--o de chaves (.reg) e persist-ncia at-mica de Undo (state.json)

function New-OptiKitBackupSession {
    [CmdletBinding()]
    param(
        [string]$SessionId
    )

    if (-not $script:OptiKit) {
        Initialize-OptiKitEnvironment | Out-Null
    }

    if ($SessionId) {
        $script:OptiKit.SessionId = $SessionId
    }
    elseif (-not $script:OptiKit.SessionId) {
        $script:OptiKit.SessionId = Get-Date -Format 'yyyy-MM-dd_HH-mm-ss'
    }

    $sessionDir = Join-Path $script:OptiKit.BackupsDir $script:OptiKit.SessionId
    if (-not $script:OptiKit.DryRun) {
        if (-not (Test-Path -LiteralPath $sessionDir)) {
            New-Item -Path $sessionDir -ItemType Directory -Force | Out-Null
        }
    }
    else {
        Write-OptimizerLog -Level DRYRUN -Message ("Criar diret$([char]0x00F3)rio de sess$([char]0x00E3)o de backup: {0}" -f $sessionDir)
    }

    $script:OptiKit.SessionDir = $sessionDir
    return $sessionDir
}

function ConvertTo-RegExePath {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$PsPath
    )

    $clean = $PsPath.Trim()
    $clean = $clean -replace '^Microsoft\.PowerShell\.Core\\Registry::', ''
    $clean = $clean -replace '^HKEY_LOCAL_MACHINE\\', 'HKLM\'
    $clean = $clean -replace '^HKEY_CURRENT_USER\\', 'HKCU\'
    $clean = $clean -replace '^HKEY_CLASSES_ROOT\\', 'HKCR\'
    $clean = $clean -replace '^HKEY_USERS\\', 'HKU\'
    $clean = $clean -replace '^HKLM:\\?', 'HKLM\'
    $clean = $clean -replace '^HKCU:\\?', 'HKCU\'
    $clean = $clean -replace '^HKCR:\\?', 'HKCR\'
    $clean = $clean -replace '^HKU:\\?', 'HKU\'
    return $clean
}

function Export-RegistryKeyBackup {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [AllowEmptyCollection()]
        [string[]]$Paths,

        [string]$DestinationDir
    )

    if (-not $Paths -or $Paths.Count -eq 0) {
        return @()
    }

    if (-not $DestinationDir) {
        if (-not $script:OptiKit.SessionDir) {
            New-OptiKitBackupSession | Out-Null
        }
        $DestinationDir = $script:OptiKit.SessionDir
    }

    $exportedFiles = New-Object 'System.Collections.Generic.List[string]'
    $uniquePaths = $Paths | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique

    foreach ($psPath in $uniquePaths) {
        $regPath = ConvertTo-RegExePath -PsPath $psPath
        $safeName = ($regPath -replace '[\\/:*?"<>|\s\{\}]', '_') + '.reg'
        $outFile = Join-Path $DestinationDir $safeName

        if ($script:OptiKit -and $script:OptiKit.DryRun) {
            Write-OptimizerLog -Level DRYRUN -Message ("Exportar chave de registro '{0}' para '{1}'" -f $regPath, $outFile)
            [void]$exportedFiles.Add($outFile)
            continue
        }

        if (-not (Test-Path -LiteralPath $psPath)) {
            Write-OptimizerLog -Level INFO -Message ("Chave '{0}' ainda n$([char]0x00E3)o existe no sistema (sem necessidade de export .reg)." -f $psPath)
            continue
        }

        try {
            if (-not (Test-Path -LiteralPath $DestinationDir)) {
                New-Item -Path $DestinationDir -ItemType Directory -Force | Out-Null
            }
            $proc = Start-Process -FilePath 'reg.exe' -ArgumentList @('export', $regPath, $outFile, '/y') -NoNewWindow -Wait -PassThru
            if ($proc.ExitCode -eq 0 -and (Test-Path -LiteralPath $outFile)) {
                Write-OptimizerLog -Level OK -Message ("Backup de registro salvo: {0}" -f $safeName)
                [void]$exportedFiles.Add($outFile)
            }
            else {
                Write-OptimizerLog -Level WARN -Message ("reg.exe export retornou c$([char]0x00F3)digo {0} para '{1}'" -f $proc.ExitCode, $regPath)
            }
        }
        catch {
            Write-OptimizerLog -Level WARN -Message ("Falha ao exportar '{0}': {1}" -f $regPath, $_.Exception.Message)
        }
    }

    return $exportedFiles.ToArray()
}

function Read-OptiKitStateFile {
    [CmdletBinding()]
    param(
        [string]$StateFilePath
    )

    if (-not $StateFilePath) {
        $StateFilePath = $script:OptiKit.StateFile
    }

    $result = @{}
    if (-not $StateFilePath -or -not (Test-Path -LiteralPath $StateFilePath)) {
        return $result
    }

    try {
        $raw = [System.IO.File]::ReadAllText($StateFilePath, [System.Text.Encoding]::UTF8)
        if ([string]::IsNullOrWhiteSpace($raw)) {
            return $result
        }
        $parsed = $raw | ConvertFrom-Json
        if ($null -ne $parsed) {
            foreach ($prop in $parsed.PSObject.Properties) {
                $result[$prop.Name] = $prop.Value
            }
        }
    }
    catch {
        $readError = $_.Exception.Message
        $quarantinePath = "{0}.corrupt-{1}" -f $StateFilePath, (Get-Date -Format 'yyyyMMdd-HHmmss')

        if ($script:OptiKit -and $script:OptiKit.DryRun) {
            Write-OptimizerLog -Level WARN -Message ("state.json ileg$([char]0x00ED)vel em '{0}': {1}. DryRun ativo; arquivo n$([char]0x00E3)o foi movido para '{2}'." -f $StateFilePath, $readError, $quarantinePath)
        }
        else {
            try {
                Move-Item -LiteralPath $StateFilePath -Destination $quarantinePath -Force -ErrorAction Stop
                Write-OptimizerLog -Level ERROR -Message ("state.json ileg$([char]0x00ED)vel em '{0}': {1}. Arquivo movido para '{2}'." -f $StateFilePath, $readError, $quarantinePath)
            }
            catch {
                Write-OptimizerLog -Level WARN -Message ("state.json ileg$([char]0x00ED)vel em '{0}' ({1}) e falha ao mover para '{2}': {3}" -f $StateFilePath, $readError, $quarantinePath, $_.Exception.Message)
            }
        }
    }

    return $result
}

function Write-OptiKitStateFile {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [hashtable]$StateData,

        [string]$StateFilePath
    )

    if (-not $StateFilePath) {
        $StateFilePath = $script:OptiKit.StateFile
    }

    if ($script:OptiKit -and $script:OptiKit.DryRun) {
        Write-OptimizerLog -Level DRYRUN -Message ("Atualizar arquivo de estado '{0}' ({1} entradas)" -f $StateFilePath, $StateData.Count)
        return
    }

    $parentDir = Split-Path -Path $StateFilePath -Parent
    if ($parentDir -and -not (Test-Path -LiteralPath $parentDir)) {
        New-Item -Path $parentDir -ItemType Directory -Force | Out-Null
    }

    $tmpFile = "{0}.{1}.tmp" -f $StateFilePath, [Guid]::NewGuid().ToString('N')
    $utf8Bom = New-Object System.Text.UTF8Encoding($true)
    $json = [pscustomobject]$StateData | ConvertTo-Json -Depth 10

    try {
        [System.IO.File]::WriteAllText($tmpFile, $json, $utf8Bom)
        if ([System.IO.File]::Exists($StateFilePath)) {
            [System.IO.File]::Replace($tmpFile, $StateFilePath, [NullString]::Value)
        }
        else {
            [System.IO.File]::Move($tmpFile, $StateFilePath)
        }

        if ($script:OptiKit -and $script:OptiKit.SessionDir -and (Test-Path -LiteralPath $script:OptiKit.SessionDir)) {
            $snapshotPath = Join-Path $script:OptiKit.SessionDir 'state-snapshot.json'
            [System.IO.File]::WriteAllText($snapshotPath, $json, $utf8Bom)
        }
    }
    catch {
        if (Test-Path -LiteralPath $tmpFile) {
            Remove-Item -LiteralPath $tmpFile -Force -ErrorAction SilentlyContinue
        }
        Write-OptimizerLog -Level WARN -Message ("Falha na escrita at$([char]0x00F4)mica do state.json: {0}" -f $_.Exception.Message)
        throw
    }
}

function Save-CapturedState {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Id,

        [Parameter(Mandatory = $true)]
        [AllowEmptyCollection()]
        [array]$CapturedItems,

        [switch]$ForceOverwrite,
        [string]$StateFilePath
    )

    if ($script:OptiKit -and $script:OptiKit.DryRun) {
        Write-OptimizerLog -Level DRYRUN -Message ("Capturar estado original para '{0}' ({1} itens)" -f $Id, $CapturedItems.Count)
        return
    }

    $state = Read-OptiKitStateFile -StateFilePath $StateFilePath
    if ($state.ContainsKey($Id) -and -not $ForceOverwrite) {
        Write-OptimizerLog -Level INFO -Message ("Estado original de '{0}' j$([char]0x00E1) est$([char]0x00E1) preservado no state.json (first-capture-wins)." -f $Id)
        return
    }

    $state[$Id] = [pscustomobject]@{
        appliedAt = (Get-Date -Format 'o')
        session   = if ($script:OptiKit -and $script:OptiKit.SessionId) { $script:OptiKit.SessionId } else { (Get-Date -Format 'yyyy-MM-dd_HH-mm-ss') }
        captured  = @($CapturedItems)
    }

    Write-OptiKitStateFile -StateData $state -StateFilePath $StateFilePath
}

function Get-CapturedState {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Id,

        [string]$StateFilePath
    )

    $state = Read-OptiKitStateFile -StateFilePath $StateFilePath
    if ($state.ContainsKey($Id)) {
        return $state[$Id]
    }
    return $null
}

function Remove-CapturedState {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$Id,

        [string]$StateFilePath
    )

    if ($script:OptiKit -and $script:OptiKit.DryRun) {
        Write-OptimizerLog -Level DRYRUN -Message ("Remover entrada '{0}' do state.json ap$([char]0x00F3)s Undo" -f $Id)
        return
    }

    $state = Read-OptiKitStateFile -StateFilePath $StateFilePath
    if ($state.ContainsKey($Id)) {
        [void]$state.Remove($Id)
        Write-OptiKitStateFile -StateData $state -StateFilePath $StateFilePath
    }
}

function New-OptiKitRestorePoint {
    [CmdletBinding()]
    param(
        [string]$Description = "OptiKit - Antes de aplicar otimiza$([char]0x00E7)$([char]0x00F5)es",
        [scriptblock]$ConfirmEnableProtection
    )

    if ($script:OptiKit -and $script:OptiKit.DryRun) {
        Write-OptimizerLog -Level DRYRUN -Message ("Criar Ponto de Restaura$([char]0x00E7)$([char]0x00E3)o do Sistema: '{0}'" -f $Description)
        return $true
    }

    $srKey = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore'
    $hadFreqValue = $false
    $prevFreqValue = $null

    try {
        $rpInterval = 0
        if (Test-Path -LiteralPath $srKey) {
            $srProps = Get-ItemProperty -LiteralPath $srKey -ErrorAction SilentlyContinue
            if ($null -ne $srProps -and $null -ne $srProps.RPSessionInterval) {
                $rpInterval = [int]$srProps.RPSessionInterval
            }
            if ($null -ne $srProps -and ($srProps.PSObject.Properties.Name -contains 'SystemRestorePointCreationFrequency')) {
                $hadFreqValue = $true
                $prevFreqValue = $srProps.SystemRestorePointCreationFrequency
            }
        }

        if ($rpInterval -eq 0) {
            $shouldEnable = $false
            if ($ConfirmEnableProtection) {
                $shouldEnable = [bool](& $ConfirmEnableProtection)
            }
            if ($shouldEnable) {
                Write-OptimizerLog -Level INFO -Message "Ativando Prote$([char]0x00E7)$([char]0x00E3)o do Sistema na unidade C:\..."
                Enable-ComputerRestore -Drive 'C:\' -ErrorAction Stop
            }
            else {
                Write-OptimizerLog -Level WARN -Message "Prote$([char]0x00E7)$([char]0x00E3)o do Sistema desativada em C:\. Seguindo com backup .reg e state.json."
                return $false
            }
        }

        if (-not (Test-Path -LiteralPath $srKey)) {
            New-Item -Path $srKey -Force | Out-Null
        }
        Set-ItemProperty -LiteralPath $srKey -Name 'SystemRestorePointCreationFrequency' -Value 0 -Type DWord -ErrorAction Stop

        Write-OptimizerLog -Level INFO -Message ("Criando Ponto de Restaura$([char]0x00E7)$([char]0x00E3)o: '{0}'..." -f $Description)
        Checkpoint-Computer -Description $Description -RestorePointType 'MODIFY_SETTINGS' -ErrorAction Stop
        Write-OptimizerLog -Level OK -Message "Ponto de Restaura$([char]0x00E7)$([char]0x00E3)o do Sistema criado com sucesso."
        return $true
    }
    catch {
        Write-OptimizerLog -Level WARN -Message ("N$([char]0x00E3)o foi poss$([char]0x00ED)vel criar Ponto de Restaura$([char]0x00E7)$([char]0x00E3)o ({0}). Os backups .reg e state.json continuam ativos." -f $_.Exception.Message)
        return $false
    }
    finally {
        try {
            if (Test-Path -LiteralPath $srKey) {
                if ($hadFreqValue) {
                    Set-ItemProperty -LiteralPath $srKey -Name 'SystemRestorePointCreationFrequency' -Value $prevFreqValue -Type DWord -ErrorAction SilentlyContinue
                }
                else {
                    Remove-ItemProperty -LiteralPath $srKey -Name 'SystemRestorePointCreationFrequency' -ErrorAction SilentlyContinue
                }
            }
        }
        catch {
            Write-Verbose ("Erro ao restaurar SystemRestorePointCreationFrequency: {0}" -f $_.Exception.Message)
        }
    }
}

# ============================================================================
# Module: src/windows/modules/hardware-utils.ps1
# ============================================================================
# Detec--o de Hardware (CPU/GPU/Chassi/SSD/Build) e Otimiza--es de Energia e Portas USB

function Resolve-OptiKitCpuFlags {
    [CmdletBinding()]
    param(
        [string]$CpuName,
        [int]$CpuCores
    )

    $isX3D = [bool]($CpuName -match '(?i)\b\d{4}(?:HX|X)3D\b')
    $isX3DDualCcd = $isX3D -and (($CpuName -match '(?i)\b(79|99)\d{2}(?:HX|X)3D\b') -or ($CpuCores -gt 8))

    [pscustomobject]@{
        IsX3D        = $isX3D
        IsX3DDualCcd = $isX3DDualCcd
    }
}

function Get-OptiKitHardware {
    [CmdletBinding()]
    param(
        [switch]$Force
    )

    if ($script:OptiKitHardwareCache -and -not $Force) {
        return $script:OptiKitHardwareCache
    }

    $cpuName = 'CPU Desconhecida'
    try {
        $regCpu = Get-ItemProperty -LiteralPath 'HKLM:\HARDWARE\DESCRIPTION\System\CentralProcessor\0' -Name 'ProcessorNameString' -ErrorAction SilentlyContinue
        if ($regCpu -and $regCpu.ProcessorNameString) {
            $cpuName = $regCpu.ProcessorNameString.Trim()
        }
    }
    catch {
        Write-Verbose ("Falha ao ler nome da CPU do registro: {0}" -f $_.Exception.Message)
    }

    $cpuCores = 0
    try {
        $cpuCim = Get-CimInstance -ClassName Win32_Processor -ErrorAction SilentlyContinue
        if ($cpuCim) {
            $cpuCores = [int](($cpuCim | Measure-Object -Property NumberOfCores -Sum).Sum)
        }
    }
    catch {
        Write-Verbose ("Falha ao obter n$([char]0x00FA)mero de n$([char]0x00FA)cleos da CPU: {0}" -f $_.Exception.Message)
    }

    # X3D dual-CCD: 7900X3D/7950X3D/9900X3D/9950X3D (12/16 n-cleos). Single-CCD X3D tem at- 8.
    $cpuFlags = Resolve-OptiKitCpuFlags -CpuName $cpuName -CpuCores $cpuCores
    $isX3D = $cpuFlags.IsX3D
    $isX3DDualCcd = $cpuFlags.IsX3DDualCcd

    $isLaptop = $false
    try {
        $enclosure = Get-CimInstance -ClassName Win32_SystemEnclosure -ErrorAction SilentlyContinue
        $laptopChassis = @(8, 9, 10, 11, 12, 14, 18, 21, 30, 31, 32)
        if ($enclosure -and $enclosure.ChassisTypes) {
            foreach ($ct in $enclosure.ChassisTypes) {
                if ($laptopChassis -contains [int]$ct) {
                    $isLaptop = $true
                    break
                }
            }
        }
        if (-not $isLaptop) {
            $battery = Get-CimInstance -ClassName Win32_Battery -ErrorAction SilentlyContinue
            if ($battery) {
                $isLaptop = $true
            }
        }
    }
    catch {
        Write-Verbose ("Falha ao detectar chassi/bateria via CIM: {0}" -f $_.Exception.Message)
    }

    $gpuNames = New-Object 'System.Collections.Generic.List[string]'
    $gpuVendors = New-Object 'System.Collections.Generic.List[string]'
    try {
        $gpus = Get-CimInstance -ClassName Win32_VideoController -ErrorAction SilentlyContinue
        foreach ($g in $gpus) {
            if ($g.Name) {
                [void]$gpuNames.Add($g.Name.Trim())
                if ($g.Name -match '(?i)NVIDIA|GeForce|RTX|GTX') {
                    if (-not $gpuVendors.Contains('NVIDIA')) { [void]$gpuVendors.Add('NVIDIA') }
                }
                elseif ($g.Name -match '(?i)AMD|Radeon|RX\s') {
                    if (-not $gpuVendors.Contains('AMD')) { [void]$gpuVendors.Add('AMD') }
                }
                elseif ($g.Name -match '(?i)Intel|Arc|Iris|UHD') {
                    if (-not $gpuVendors.Contains('Intel')) { [void]$gpuVendors.Add('Intel') }
                }
            }
        }
    }
    catch {
        Write-Verbose ("Falha ao detectar GPUs via CIM: {0}" -f $_.Exception.Message)
    }

    $isSsd = $true
    try {
        if (Get-Command Get-PhysicalDisk -ErrorAction SilentlyContinue) {
            $disks = Get-PhysicalDisk -ErrorAction SilentlyContinue
            if ($disks) {
                $hddOnly = ($disks | Where-Object { $_.MediaType -eq 'SSD' }).Count -eq 0 -and ($disks | Where-Object { $_.MediaType -eq 'HDD' }).Count -gt 0
                if ($hddOnly) { $isSsd = $false }
            }
        }
    }
    catch {
        Write-Verbose ("Falha ao detectar tipo de disco: {0}" -f $_.Exception.Message)
    }

    $osBuild = [int][Environment]::OSVersion.Version.Build
    $isWin11 = ($osBuild -ge 22000)
    $osLabel = if ($isWin11) { "Windows 11 (Build $osBuild)" } else { "Windows 10 (Build $osBuild)" }
    $chassisLabel = if ($isLaptop) { 'Notebook' } else { 'Desktop' }
    $gpuPrimary = if ($gpuNames.Count -gt 0) { $gpuNames[0] } else { "GPU Padr$([char]0x00E3)o" }

    $script:OptiKitHardwareCache = [pscustomobject]@{
        CpuName         = $cpuName
        CpuCores        = $cpuCores
        IsX3D           = $isX3D
        IsX3DDualCcd    = $isX3DDualCcd
        IsLaptop        = $isLaptop
        GpuNames        = $gpuNames.ToArray()
        GpuVendors      = $gpuVendors.ToArray()
        SystemDiskIsSSD = $isSsd
        OsBuild         = $osBuild
        IsWin11         = $isWin11
        Summary         = "$cpuName | $gpuPrimary | $chassisLabel | $osLabel"
    }

    return $script:OptiKitHardwareCache
}

function Test-OptiKitTweakBlocked {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$Tweak,

        [pscustomobject]$Hardware
    )

    $guards = @($Tweak.blockedOn)
    if ($guards.Count -eq 0) {
        return $null
    }

    if (-not $Hardware) {
        $Hardware = Get-OptiKitHardware
    }

    foreach ($guard in $guards) {
        $isBlocked = switch ([string]$guard) {
            'X3DDualCcd' { [bool]$Hardware.IsX3DDualCcd }
            'X3D'        { [bool]$Hardware.IsX3D }
            'Laptop'     { [bool]$Hardware.IsLaptop }
            default      { $false }
        }

        if ($isBlocked) {
            if (-not [string]::IsNullOrWhiteSpace($Tweak.blockedMessage)) {
                return [string]$Tweak.blockedMessage
            }
            return ("Bloqueado neste hardware ({0})." -f $guard)
        }
    }

    return $null
}

function Test-OptiKitTweakSupported {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$Tweak,

        [pscustomobject]$Hardware
    )

    if (-not $Hardware) {
        $Hardware = Get-OptiKitHardware
    }

    $supportedOs = @()
    if ($null -ne $Tweak.osSupport) {
        $supportedOs = @($Tweak.osSupport | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
    }

    if ($supportedOs.Count -gt 0) {
        $osTag = if ($Hardware.IsWin11) { 'Win11' } else { 'Win10' }
        if ($supportedOs -notcontains $osTag) {
            return $false
        }
    }

    if ($null -ne $Tweak.minBuild -and [int]$Hardware.OsBuild -lt [int]$Tweak.minBuild) {
        return $false
    }

    return $true
}

function Get-ActivePowerPlanGuid {
    [CmdletBinding()]
    param()

    try {
        $out = & powercfg.exe /getactivescheme 2>$null | Out-String
        if ($out -match '([0-9a-fA-F]{8}-([0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12})') {
            return $Matches[1].ToLowerInvariant()
        }
    }
    catch {
        Write-Verbose ("Erro ao obter plano de energia ativo: {0}" -f $_.Exception.Message)
    }
    return '381b4222-f694-41f0-9685-ff5bb260df2e'
}

function Set-OptiKitSmartPowerPlan {
    [CmdletBinding()]
    param()

    $hw = Get-OptiKitHardware
    $currentGuid = Get-ActivePowerPlanGuid
    Save-CapturedState -Id 'PowerPlanOriginal' -CapturedItems @(
        @{ kind = 'powerplan'; guid = $currentGuid }
    )

    $balancedGuid = '381b4222-f694-41f0-9685-ff5bb260df2e'
    $highPerfGuid = '8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c'

    if ($hw.IsLaptop) {
        Write-OptimizerLog -Level INFO -Message "Notebook detectado: mantendo plano Equilibrado (Balanced) para preservar autonomia e gerenciamento t$([char]0x00E9)rmico."
        Invoke-Mutation -Description 'Ativar plano Equilibrado (Balanced) para Notebook' -Action {
            & powercfg.exe /setactive $balancedGuid | Out-Null
        } | Out-Null
        return
    }

    if ($hw.IsX3D) {
        Write-OptimizerLog -Level INFO -Message ("CPU AMD Ryzen X3D detectada ({0}): recomendando e ativando plano Equilibrado (exigido pelo Core Parking do 3D V-Cache)." -f $hw.CpuName)
        Invoke-Mutation -Description "Ativar plano Equilibrado para AMD Ryzen X3D (sem suspens$([char]0x00E3)o autom$([char]0x00E1)tica em Desktop)" -Action {
            & powercfg.exe /setactive $balancedGuid | Out-Null
            & powercfg.exe /change standby-timeout-ac 0 | Out-Null
        } | Out-Null
        return
    }

    Invoke-Mutation -Description "Ativar plano de energia Alto Desempenho (Desktop) e desativar suspens$([char]0x00E3)o autom$([char]0x00E1)tica" -Action {
        if (-not (Test-OptiKitUltimatePowerPlan)) {
            & powercfg.exe /setactive $highPerfGuid | Out-Null
        }
        & powercfg.exe /change standby-timeout-ac 0 | Out-Null
    } | Out-Null
}

function Enable-OptiKitUltimatePowerPlan {
    [CmdletBinding()]
    param()

    $currentGuid = Get-ActivePowerPlanGuid
    Save-CapturedState -Id 'PowerPlanOriginal' -CapturedItems @(
        @{ kind = 'powerplan'; guid = $currentGuid }
    )

    $ultimateTemplate = 'e9a42b02-d5df-448d-aa00-03f14749eb61'
    Invoke-Mutation -Description 'Desbloquear e ativar plano Ultimate Performance (sem duplicar)' -Action {
        $listOut = & powercfg.exe /list 2>$null | Out-String
        $targetGuid = $null

        foreach ($line in ($listOut -split "\r?\n")) {
            if ($line -match '(?i)(e9a42b02-d5df-448d-aa00-03f14749eb61|Ultimate Performance|Desempenho M.ximo)' -and
                $line -match '([0-9a-fA-F]{8}-([0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12})') {
                $targetGuid = $Matches[1].ToLowerInvariant()
                break
            }
        }

        if (-not $targetGuid) {
            $dupOut = & powercfg.exe -duplicatescheme $ultimateTemplate 2>$null | Out-String
            if ($dupOut -match '([0-9a-fA-F]{8}-([0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12})') {
                $targetGuid = $Matches[1].ToLowerInvariant()
            }
            else {
                $targetGuid = $ultimateTemplate
            }
        }

        & powercfg.exe /setactive $targetGuid | Out-Null
        & powercfg.exe /change standby-timeout-ac 0 | Out-Null
    } | Out-Null
}

function Restore-OptiKitPowerPlan {
    [CmdletBinding()]
    param()

    $captured = Get-CapturedState -Id 'PowerPlanOriginal'
    $targetGuid = '381b4222-f694-41f0-9685-ff5bb260df2e'
    if ($captured -and $captured.captured -and $captured.captured.Count -gt 0 -and $captured.captured[0].guid) {
        $targetGuid = $captured.captured[0].guid
    }

    Invoke-Mutation -Description ("Restaurar plano de energia anterior ({0})" -f $targetGuid) -Action {
        & powercfg.exe /setactive $targetGuid | Out-Null
    } | Out-Null

    Remove-CapturedState -Id 'PowerPlanOriginal'
}

function Test-OptiKitSmartPowerPlan {
    [CmdletBinding()]
    param()

    $hw = Get-OptiKitHardware
    $active = Get-ActivePowerPlanGuid
    if ($hw.IsLaptop -or $hw.IsX3D) {
        return ($active -eq '381b4222-f694-41f0-9685-ff5bb260df2e')
    }
    return (($active -eq '8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c') -or (Test-OptiKitUltimatePowerPlan))
}

function Test-OptiKitUltimatePowerPlan {
    [CmdletBinding()]
    param()

    try {
        $out = & powercfg.exe /getactivescheme 2>$null | Out-String
        return [bool]($out -match '(?i)(e9a42b02-d5df-448d-aa00-03f14749eb61|Ultimate Performance|Desempenho M.ximo)')
    }
    catch {
        return $false
    }
}

function Disable-OptiKitHibernation {
    [CmdletBinding()]
    param()

    Invoke-Mutation -Description "Desativar hiberna$([char]0x00E7)$([char]0x00E3)o via powercfg /hibernate off" -Action {
        & powercfg.exe /hibernate off | Out-Null
    } | Out-Null
}

function Enable-OptiKitHibernation {
    [CmdletBinding()]
    param()

    Invoke-Mutation -Description "Reativar hiberna$([char]0x00E7)$([char]0x00E3)o via powercfg /hibernate on" -Action {
        & powercfg.exe /hibernate on | Out-Null
    } | Out-Null
}

function Optimize-UsbPower {
    [CmdletBinding()]
    param()

    $usbSubGroup = '2a737441-1930-4402-8d77-b2bebba308a3'
    $usbSelectiveSuspend = '48e6b7a6-50f5-4782-a5d4-53bb8f07e226'
    $usbSettingsKey = 'HKLM:\SYSTEM\CurrentControlSet\Services\USB'

    $existed = $false
    $prevVal = $null
    if (Test-Path -LiteralPath $usbSettingsKey) {
        $prop = Get-ItemProperty -LiteralPath $usbSettingsKey -Name 'DisableSelectiveSuspend' -ErrorAction SilentlyContinue
        if ($null -ne $prop -and ($prop.PSObject.Properties.Name -contains 'DisableSelectiveSuspend')) {
            $existed = $true
            $prevVal = $prop.DisableSelectiveSuspend
        }
    }

    Save-CapturedState -Id 'UsbPowerOptimization' -CapturedItems @(
        @{ kind = 'registry'; path = $usbSettingsKey; name = 'DisableSelectiveSuspend'; existed = $existed; type = 'DWord'; value = $prevVal }
    )

    Invoke-Mutation -Description "Desativar Suspens$([char]0x00E3)o Seletiva de USB no plano de energia ativo e no controlador USB" -Action {
        & powercfg.exe /setacvalueindex SCHEME_CURRENT $usbSubGroup $usbSelectiveSuspend 0 | Out-Null
        & powercfg.exe /setactive SCHEME_CURRENT | Out-Null

        if (-not (Test-Path -LiteralPath $usbSettingsKey)) {
            New-Item -Path $usbSettingsKey -Force | Out-Null
        }
        Set-ItemProperty -LiteralPath $usbSettingsKey -Name 'DisableSelectiveSuspend' -Value 1 -Type DWord -ErrorAction Stop

        $hubs = Get-CimInstance -Namespace 'root\wmi' -ClassName 'MSPower_DeviceEnable' -ErrorAction SilentlyContinue |
            Where-Object { $_.InstanceName -match '(?i)^USB\\(ROOT_HUB|VID_)' }
        foreach ($hub in $hubs) {
            if ($hub.Enable -eq $true) {
                $hub.Enable = $false
                Set-CimInstance -InputObject $hub -ErrorAction SilentlyContinue | Out-Null
            }
        }
    } | Out-Null
}

function Restore-UsbPower {
    [CmdletBinding()]
    param()

    $usbSubGroup = '2a737441-1930-4402-8d77-b2bebba308a3'
    $usbSelectiveSuspend = '48e6b7a6-50f5-4782-a5d4-53bb8f07e226'
    $usbSettingsKey = 'HKLM:\SYSTEM\CurrentControlSet\Services\USB'
    $captured = Get-CapturedState -Id 'UsbPowerOptimization'

    Invoke-Mutation -Description "Restaurar configura$([char]0x00E7)$([char]0x00F5)es padr$([char]0x00E3)o de Suspens$([char]0x00E3)o Seletiva de USB" -Action {
        & powercfg.exe /setacvalueindex SCHEME_CURRENT $usbSubGroup $usbSelectiveSuspend 1 | Out-Null
        & powercfg.exe /setactive SCHEME_CURRENT | Out-Null

        if ($captured -and $captured.captured -and $captured.captured.Count -gt 0 -and $captured.captured[0].existed) {
            Set-ItemProperty -LiteralPath $usbSettingsKey -Name 'DisableSelectiveSuspend' -Value $captured.captured[0].value -Type DWord -ErrorAction SilentlyContinue
        }
        elseif (Test-Path -LiteralPath $usbSettingsKey) {
            Remove-ItemProperty -LiteralPath $usbSettingsKey -Name 'DisableSelectiveSuspend' -ErrorAction SilentlyContinue
        }
    } | Out-Null

    Remove-CapturedState -Id 'UsbPowerOptimization'
}

function Test-UsbPowerOptimized {
    [CmdletBinding()]
    param()

    $usbSettingsKey = 'HKLM:\SYSTEM\CurrentControlSet\Services\USB'
    if (-not (Test-Path -LiteralPath $usbSettingsKey)) {
        return $false
    }
    $prop = Get-ItemProperty -LiteralPath $usbSettingsKey -Name 'DisableSelectiveSuspend' -ErrorAction SilentlyContinue
    return ($null -ne $prop -and $prop.DisableSelectiveSuspend -eq 1)
}

# ============================================================================
# Module: src/windows/modules/winget-engine.ps1
# ============================================================================
# Motor Winget (verifica--o, bootstrap oficial com verifica--o Authenticode, instala--o silenciosa) e gest-o segura do OneDrive

function Test-WingetAvailable {
    [CmdletBinding()]
    param()

    $wingetCmd = Get-Command 'winget.exe' -ErrorAction SilentlyContinue
    $wingetPath = if ($wingetCmd) { $wingetCmd.Source } else { Join-Path $env:LOCALAPPDATA 'Microsoft\WindowsApps\winget.exe' }

    if (-not $wingetPath -or -not (Test-Path -LiteralPath $wingetPath)) {
        return [pscustomobject]@{
            Available = $false
            Path      = $null
            Version   = $null
            IsHealthy = $false
        }
    }

    try {
        $verRaw = (& $wingetPath --version 2>$null | Out-String).Trim()
        $cleanVer = $verRaw -replace '^v', '' -replace '-.*$', ''
        $parsedVer = $null
        $isHealthy = [version]::TryParse($cleanVer, [ref]$parsedVer) -and ($parsedVer -ge [version]'1.6.0')
        return [pscustomobject]@{
            Available = $true
            Path      = $wingetPath
            Version   = $verRaw
            IsHealthy = $isHealthy
        }
    }
    catch {
        return [pscustomobject]@{
            Available = $false
            Path      = $wingetPath
            Version   = $null
            IsHealthy = $false
        }
    }
}

function Install-WingetBootstrap {
    [CmdletBinding()]
    param()

    if ($script:OptiKit -and $script:OptiKit.DryRun) {
        Write-OptimizerLog -Level DRYRUN -Message 'Instalar/reparar Microsoft App Installer (Winget Bootstrap)'
        return $true
    }

    Write-OptimizerLog -Level INFO -Message 'Verificando disponibilidade e integridade do Winget...'
    if (Get-Command 'Repair-WinGetPackageManager' -ErrorAction SilentlyContinue) {
        try {
            Write-OptimizerLog -Level INFO -Message 'Tentando reparo via Repair-WinGetPackageManager...'
            Repair-WinGetPackageManager -AllUsers -ErrorAction Stop
            if ((Test-WingetAvailable).IsHealthy) {
                Write-OptimizerLog -Level OK -Message 'Winget reparado com sucesso via Microsoft.WinGet.Client.'
                return $true
            }
        }
        catch {
            Write-OptimizerLog -Level WARN -Message ("Repair-WinGetPackageManager falhou: {0}. Tentando pacote oficial do GitHub..." -f $_.Exception.Message)
        }
    }

    $tempDir = Join-Path $env:TEMP ("optikit_winget_" + [Guid]::NewGuid().ToString('N'))
    New-Item -Path $tempDir -ItemType Directory -Force | Out-Null

    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        $vcLibsUrl = 'https://aka.ms/Microsoft.VCLibs.x64.14.00.Desktop.appx'
        $vcLibsFile = Join-Path $tempDir 'Microsoft.VCLibs.x64.14.00.Desktop.appx'
        Write-OptimizerLog -Level INFO -Message "Baixando depend$([char]0x00EA)ncia VCLibs Desktop..."
        Invoke-WebRequest -Uri $vcLibsUrl -OutFile $vcLibsFile -UseBasicParsing -ErrorAction Stop
        Add-AppxPackage -Path $vcLibsFile -ErrorAction SilentlyContinue

        $relApi = 'https://api.github.com/repos/microsoft/winget-cli/releases/latest'
        $release = Invoke-RestMethod -Uri $relApi -UseBasicParsing -ErrorAction Stop
        $bundleAsset = $release.assets | Where-Object { $_.name -match '\.msixbundle$' } | Select-Object -First 1
        if (-not $bundleAsset) {
            throw "Asset .msixbundle n$([char]0x00E3)o encontrado na release oficial microsoft/winget-cli."
        }

        $bundlePath = Join-Path $tempDir $bundleAsset.name
        Write-OptimizerLog -Level INFO -Message ("Baixando {0}..." -f $bundleAsset.name)
        Invoke-WebRequest -Uri $bundleAsset.browser_download_url -OutFile $bundlePath -UseBasicParsing -ErrorAction Stop

        $sig = Get-AuthenticodeSignature -FilePath $bundlePath
        if ($sig.Status -ne 'Valid') {
            throw ("Assinatura Authenticode inv$([char]0x00E1)lida para {0} (Status: {1})" -f $bundlePath, $sig.Status)
        }

        Add-AppxPackage -Path $bundlePath -ErrorAction Stop
        $status = Test-WingetAvailable
        if ($status.Available) {
            Write-OptimizerLog -Level OK -Message ("Winget instalado com sucesso ({0})." -f $status.Version)
            return $true
        }
        return $false
    }
    catch {
        Write-OptimizerLog -Level ERROR -Message ("Falha no bootstrap do Winget: {0}" -f $_.Exception.Message)
        return $false
    }
    finally {
        if (Test-Path -LiteralPath $tempDir) {
            Remove-Item -LiteralPath $tempDir -Recurse -Force -ErrorAction SilentlyContinue
        }
    }
}

function Install-OptiKitApp {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$AppKey,

        [Parameter(Mandatory = $true)]
        [pscustomobject]$AppConfig
    )

    $wingetId = $AppConfig.winget
    $displayName = if ($AppConfig.name) { $AppConfig.name } else { $AppKey }

    if ([string]::IsNullOrWhiteSpace($wingetId)) {
        Write-OptimizerLog -Level WARN -Message ("Aplicativo '{0}' n$([char]0x00E3)o possui ID do Winget mapeado." -f $displayName)
        return $false
    }

    if ($script:OptiKit -and $script:OptiKit.DryRun) {
        Write-OptimizerLog -Level DRYRUN -Message ("Instalar aplicativo via Winget: {0} ({1})" -f $displayName, $wingetId)
        return $true
    }

    $wg = Test-WingetAvailable
    if (-not $wg.Available) {
        Write-OptimizerLog -Level WARN -Message "Winget n$([char]0x00E3)o encontrado. Iniciando instala$([char]0x00E7)$([char]0x00E3)o autom$([char]0x00E1)tica do App Installer..."
        if (-not (Install-WingetBootstrap)) {
            Write-OptimizerLog -Level ERROR -Message ("N$([char]0x00E3)o foi poss$([char]0x00ED)vel instalar '{0}' porque o Winget est$([char]0x00E1) indispon$([char]0x00ED)vel." -f $displayName)
            return $false
        }
        $wg = Test-WingetAvailable
    }

    Write-OptimizerLog -Level INFO -Message ("Instalando {0} ({1})..." -f $displayName, $wingetId)
    $wingetArgs = @(
        'install',
        '--id', $wingetId,
        '--exact',
        '--silent',
        '--accept-package-agreements',
        '--accept-source-agreements',
        '--disable-interactivity'
    )

    try {
        $proc = Start-Process -FilePath $wg.Path -ArgumentList $wingetArgs -NoNewWindow -Wait -PassThru
        $exitCode = $proc.ExitCode
        # -1978335189 (0x8A15002B) = No applicable upgrade / already installed
        if ($exitCode -eq 0) {
            Write-OptimizerLog -Level OK -Message ("{0} instalado com sucesso." -f $displayName)
            return $true
        }
        elseif ($exitCode -eq -1978335189) {
            Write-OptimizerLog -Level INFO -Message ("{0} j$([char]0x00E1) est$([char]0x00E1) instalado na vers$([char]0x00E3)o mais recente." -f $displayName)
            return $true
        }
        elseif ($exitCode -eq 3010) {
            Write-OptimizerLog -Level OK -Message ("{0} instalado com sucesso (reinicializa$([char]0x00E7)$([char]0x00E3)o recomendada)." -f $displayName)
            return $true
        }
        else {
            Write-OptimizerLog -Level WARN -Message ("Winget retornou c$([char]0x00F3)digo {0} ao instalar {1}." -f $exitCode, $displayName)
            return $false
        }
    }
    catch {
        Write-OptimizerLog -Level ERROR -Message ("Erro ao executar Winget para {0}: {1}" -f $displayName, $_.Exception.Message)
        return $false
    }
}

function Test-OneDriveKfmActive {
    [CmdletBinding()]
    param()

    $usfPath = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders'
    if (-not (Test-Path -LiteralPath $usfPath)) {
        return $false
    }

    $props = Get-ItemProperty -LiteralPath $usfPath -ErrorAction SilentlyContinue
    if (-not $props) {
        return $false
    }

    foreach ($folderName in @('Desktop', 'Personal', 'My Pictures', '{374DE290-123F-4565-9164-39C4925E467B}')) {
        $val = $props.$folderName
        if ($val -and ($val -match '(?i)OneDrive')) {
            return $true
        }
    }
    return $false
}

function Remove-OptiKitOneDrive {
    [CmdletBinding()]
    param()

    if (Test-OneDriveKfmActive) {
        $msg = "Remo$([char]0x00E7)$([char]0x00E3)o do OneDrive bloqueada por seguran$([char]0x00E7)a: suas pastas $([char]0x00C1)rea de Trabalho/Documentos est$([char]0x00E3)o redirecionadas para o OneDrive (Known Folder Move). Desative o backup de pastas nas configura$([char]0x00E7)$([char]0x00F5)es do OneDrive antes de remov$([char]0x00EA)-lo."
        Write-OptimizerLog -Level WARN -Message $msg
        throw $msg
    }

    Invoke-Mutation -Description 'Encerrar processo e desinstalar Microsoft OneDrive' -Action {
        Stop-Process -Name 'OneDrive' -Force -ErrorAction SilentlyContinue
        $setupPaths = @(
            (Join-Path $env:SystemRoot 'System32\OneDriveSetup.exe'),
            (Join-Path $env:SystemRoot 'SysWOW64\OneDriveSetup.exe'),
            (Join-Path $env:LOCALAPPDATA 'Microsoft\OneDrive\OneDriveSetup.exe')
        )
        $setupExe = $setupPaths | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
        if ($setupExe) {
            Start-Process -FilePath $setupExe -ArgumentList '/uninstall' -NoNewWindow -Wait | Out-Null
        }
    } | Out-Null
}

function Install-OptiKitOneDrive {
    [CmdletBinding()]
    param()

    Invoke-Mutation -Description 'Reinstalar Microsoft OneDrive' -Action {
        $setupPaths = @(
            (Join-Path $env:SystemRoot 'SysWOW64\OneDriveSetup.exe'),
            (Join-Path $env:SystemRoot 'System32\OneDriveSetup.exe')
        )
        $setupExe = $setupPaths | Where-Object { Test-Path -LiteralPath $_ } | Select-Object -First 1
        if ($setupExe) {
            Start-Process -FilePath $setupExe -NoNewWindow -Wait | Out-Null
        }
        else {
            $wg = Test-WingetAvailable
            if ($wg.Available) {
                Start-Process -FilePath $wg.Path -ArgumentList @('install', '--id', 'Microsoft.OneDrive', '--exact', '--silent', '--accept-package-agreements', '--accept-source-agreements') -NoNewWindow -Wait | Out-Null
            }
        }
    } | Out-Null
}

function Test-OptiKitOneDriveRemoved {
    [CmdletBinding()]
    param()

    $exeLocal = Join-Path $env:LOCALAPPDATA 'Microsoft\OneDrive\OneDrive.exe'
    $exeProg = Join-Path ${env:ProgramFiles} 'Microsoft OneDrive\OneDrive.exe'
    return (-not (Test-Path -LiteralPath $exeLocal)) -and (-not (Test-Path -LiteralPath $exeProg))
}

function Invoke-OptiKitWingetCommand {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][string]$WingetPath,
        [Parameter(Mandatory = $true)][string[]]$Arguments,
        [Parameter(Mandatory = $true)][string]$Label
    )

    $stdoutPath = [System.IO.Path]::GetTempFileName()
    $stderrPath = [System.IO.Path]::GetTempFileName()
    try {
        $proc = Start-Process -FilePath $WingetPath -ArgumentList $Arguments -NoNewWindow -Wait -PassThru -RedirectStandardOutput $stdoutPath -RedirectStandardError $stderrPath
        foreach ($line in @(Get-Content -LiteralPath $stdoutPath -ErrorAction SilentlyContinue)) {
            if (-not [string]::IsNullOrWhiteSpace($line)) {
                Write-OptimizerLog -Level INFO -Message ("[{0}] {1}" -f $Label, $line.Trim())
            }
        }
        foreach ($line in @(Get-Content -LiteralPath $stderrPath -ErrorAction SilentlyContinue)) {
            if (-not [string]::IsNullOrWhiteSpace($line)) {
                Write-OptimizerLog -Level WARN -Message ("[{0}] {1}" -f $Label, $line.Trim())
            }
        }
        return [int]$proc.ExitCode
    }
    finally {
        Remove-Item -LiteralPath $stdoutPath, $stderrPath -Force -ErrorAction SilentlyContinue
    }
}

function Invoke-OptiKitWingetUpgrade {
    [CmdletBinding()]
    param(
        [switch]$All,
        [string[]]$Ids
    )

    $cleanIds = @($Ids | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
    if (-not $All -and $cleanIds.Count -eq 0) {
        throw 'Informe -All ou pelo menos um ID do Winget para atualizar.'
    }

    if ($script:OptiKit -and $script:OptiKit.DryRun) {
        Write-OptimizerLog -Level DRYRUN -Message ("Atualizar aplicativos via Winget ({0})" -f $(if ($All) { 'todos' } else { $cleanIds -join ', ' }))
        return $true
    }

    $wg = Test-WingetAvailable
    if (-not $wg.Available) {
        Write-OptimizerLog -Level WARN -Message "Winget n$([char]0x00E3)o encontrado. Iniciando instala$([char]0x00E7)$([char]0x00E3)o autom$([char]0x00E1)tica do App Installer..."
        if (-not (Install-WingetBootstrap)) {
            throw "Winget indispon$([char]0x00ED)vel; n$([char]0x00E3)o foi poss$([char]0x00ED)vel atualizar os aplicativos."
        }
        $wg = Test-WingetAvailable
        if (-not $wg.Available) {
            throw "Winget indispon$([char]0x00ED)vel ap$([char]0x00F3)s o bootstrap."
        }
    }

    $commands = New-Object 'System.Collections.Generic.List[pscustomobject]'
    if ($All) {
        [void]$commands.Add([pscustomobject]@{
            Label     = 'Winget upgrade --all'
            Arguments = @('upgrade', '--all', '--include-unknown', '--silent', '--accept-package-agreements', '--accept-source-agreements', '--disable-interactivity')
        })
    }
    else {
        foreach ($id in $cleanIds) {
            [void]$commands.Add([pscustomobject]@{
                Label     = ("Winget upgrade {0}" -f $id)
                Arguments = @('upgrade', '--id', $id, '--exact', '--silent', '--accept-package-agreements', '--accept-source-agreements', '--disable-interactivity')
            })
        }
    }

    $successCodes = @(0, -1978335189, 3010)
    Invoke-Mutation -Description 'Atualizar aplicativos via Winget' -Action {
        foreach ($command in $commands) {
            $exitCode = Invoke-OptiKitWingetCommand -WingetPath $wg.Path -Arguments $command.Arguments -Label $command.Label
            if ($successCodes -notcontains $exitCode) {
                throw ("{0} retornou c$([char]0x00F3)digo {1}." -f $command.Label, $exitCode)
            }
            if ($exitCode -eq -1978335189) {
                Write-OptimizerLog -Level INFO -Message ("{0}: nenhuma atualiza$([char]0x00E7)$([char]0x00E3)o aplic$([char]0x00E1)vel." -f $command.Label)
            }
            elseif ($exitCode -eq 3010) {
                Write-OptimizerLog -Level OK -Message ("{0}: atualizado; reinicializa$([char]0x00E7)$([char]0x00E3)o recomendada." -f $command.Label)
            }
            else {
                Write-OptimizerLog -Level OK -Message ("{0}: conclu$([char]0x00ED)do." -f $command.Label)
            }
        }
    } | Out-Null

    return $true
}

