# Motor de Perfis de Jogos (VALORANT, Detec--o de Execut-vel, FSO/DPI, GPU Preference, NIC Anti-Jitter, Shader Cache)

$script:AllowedGameActions = @(
    'Set-AppCompatFlags',
    'Set-DirectXGpuPreference',
    'Optimize-NetworkAdapterGaming',
    'Disable-RiotClientStartup',
    'Clear-ShaderCache',
    'Optimize-UsbPower'
)

function Find-GameExecutable {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$ProfileConfig,

        [string]$RiotInstallsPath
    )

    $det = $ProfileConfig.executableDetection
    if (-not $det) {
        return $null
    }

    foreach ($candidate in @($det.defaultPaths)) {
        if (-not [string]::IsNullOrWhiteSpace($candidate) -and (Test-Path -LiteralPath $candidate)) {
            return $candidate
        }
    }

    if (-not [string]::IsNullOrWhiteSpace($det.registryFallback)) {
        try {
            if (Test-Path -LiteralPath $det.registryFallback) {
                $props = Get-ItemProperty -LiteralPath $det.registryFallback -ErrorAction SilentlyContinue
                if ($props -and $props.InstallLocation) {
                    $baseLoc = $props.InstallLocation.Trim('"')
                    $exeFromReg = Join-Path $baseLoc 'ShooterGame\Binaries\Win64\VALORANT-Win64-Shipping.exe'
                    if (Test-Path -LiteralPath $exeFromReg) {
                        return $exeFromReg
                    }
                    $directExe = Get-ChildItem -Path $baseLoc -Filter '*-Win64-Shipping.exe' -Recurse -ErrorAction SilentlyContinue | Select-Object -First 1
                    if ($directExe) {
                        return $directExe.FullName
                    }
                }
            }
        }
        catch {
            Write-Verbose ("Erro no fallback de registro para jogo: {0}" -f $_.Exception.Message)
        }
    }

    if ($det.riotClientFallback -eq $true) {
        if (-not $RiotInstallsPath) {
            $RiotInstallsPath = Join-Path $env:ProgramData 'Riot Games\RiotClientInstalls.json'
        }

        if (Test-Path -LiteralPath $RiotInstallsPath) {
            try {
                $riotJson = [System.IO.File]::ReadAllText($RiotInstallsPath, [System.Text.Encoding]::UTF8) | ConvertFrom-Json
                if ($riotJson -and $riotJson.associated_client) {
                    foreach ($prop in $riotJson.associated_client.PSObject.Properties) {
                        $installDir = ($prop.Name -replace '/', '\').TrimEnd('\')
                        if ($installDir -match '(?i)VALORANT') {
                            $candidateExe = Join-Path $installDir 'ShooterGame\Binaries\Win64\VALORANT-Win64-Shipping.exe'
                            if (Test-Path -LiteralPath $candidateExe) {
                                return $candidateExe
                            }
                        }
                    }
                }
            }
            catch {
                Write-Verbose ("Erro ao ler RiotClientInstalls.json: {0}" -f $_.Exception.Message)
            }
        }
    }

    return $null
}

function Set-AppCompatFlags {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$ExecutablePath,

        [string]$Flags = '~ DISABLEDXMAXIMIZEDWINDOWEDMODE HIGHDPIAWARE',

        [string]$StateKey = 'Val_FSO_HighDPI',

        [ValidateSet('Apply', 'Undo')]
        [string]$Mode = 'Apply'
    )

    $layersKey = 'HKCU:\Software\Microsoft\Windows NT\CurrentVersion\AppCompatFlags\Layers'
    if ($Mode -eq 'Apply') {
        $cur = Get-RegistryEntryState -Path $layersKey -Name $ExecutablePath -FallbackType 'String'
        Save-CapturedState -Id $StateKey -CapturedItems @(
            @{ kind = 'registry'; path = $layersKey; name = $ExecutablePath; existed = $cur.ValueExisted; type = 'String'; value = $cur.Value }
        )
        Set-RegistryEntryValue -Path $layersKey -Name $ExecutablePath -Type 'String' -Value $Flags
    }
    else {
        $cap = Get-CapturedState -Id $StateKey
        if ($cap -and $cap.captured -and $cap.captured.Count -gt 0 -and $cap.captured[0].existed) {
            Set-RegistryEntryValue -Path $layersKey -Name $ExecutablePath -Type 'String' -Value $cap.captured[0].value
        }
        else {
            Set-RegistryEntryValue -Path $layersKey -Name $ExecutablePath -Type 'String' -Value '<RemoveEntry>'
        }
        Remove-CapturedState -Id $StateKey
    }
}

function Set-DirectXGpuPreference {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$ExecutablePath,

        [string]$StateKey = 'Val_DirectX_HighPerf',

        [ValidateSet('Apply', 'Undo')]
        [string]$Mode = 'Apply'
    )

    $gpuKey = 'HKCU:\Software\Microsoft\DirectX\UserGpuPreferences'
    $prefVal = 'GpuPreference=2;'

    if ($Mode -eq 'Apply') {
        $cur = Get-RegistryEntryState -Path $gpuKey -Name $ExecutablePath -FallbackType 'String'
        Save-CapturedState -Id $StateKey -CapturedItems @(
            @{ kind = 'registry'; path = $gpuKey; name = $ExecutablePath; existed = $cur.ValueExisted; type = 'String'; value = $cur.Value }
        )
        Set-RegistryEntryValue -Path $gpuKey -Name $ExecutablePath -Type 'String' -Value $prefVal
    }
    else {
        $cap = Get-CapturedState -Id $StateKey
        if ($cap -and $cap.captured -and $cap.captured.Count -gt 0 -and $cap.captured[0].existed) {
            Set-RegistryEntryValue -Path $gpuKey -Name $ExecutablePath -Type 'String' -Value $cap.captured[0].value
        }
        else {
            Set-RegistryEntryValue -Path $gpuKey -Name $ExecutablePath -Type 'String' -Value '<RemoveEntry>'
        }
        Remove-CapturedState -Id $StateKey
    }
}

function Optimize-NetworkAdapterGaming {
    [CmdletBinding()]
    param(
        [ValidateSet('Apply', 'Undo')]
        [string]$Mode = 'Apply'
    )

    $stateKey = 'NetworkAdapterGaming'
    $targetKeywords = @(
        '*EEE',
        'EEELinkAdvertisement',
        'AdvancedEEE',
        'GreenEthernet',
        'EnableGreenEthernet',
        'PowerSavingMode'
    )

    if ($Mode -eq 'Apply') {
        $capturedProps = New-Object 'System.Collections.Generic.List[hashtable]'
        if (Get-Command Get-NetAdapter -ErrorAction SilentlyContinue) {
            $adapters = Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Up' }
            foreach ($nic in $adapters) {
                $advProps = Get-NetAdapterAdvancedProperty -Name $nic.Name -ErrorAction SilentlyContinue
                foreach ($ap in $advProps) {
                    if ($targetKeywords -contains $ap.RegistryKeyword) {
                        [void]$capturedProps.Add(@{
                            adapter = $nic.Name
                            keyword = $ap.RegistryKeyword
                            value   = $ap.RegistryValue
                        })
                    }
                }
            }
        }

        Save-CapturedState -Id $stateKey -CapturedItems $capturedProps.ToArray()

        Invoke-Mutation -Description 'Desativar EEE, Green Ethernet e economia de energia no adaptador de rede ativo' -Action {
            if (-not (Get-Command Get-NetAdapter -ErrorAction SilentlyContinue)) {
                return
            }
            $adapters = Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Up' }
            foreach ($nic in $adapters) {
                $advProps = Get-NetAdapterAdvancedProperty -Name $nic.Name -ErrorAction SilentlyContinue
                foreach ($ap in $advProps) {
                    if ($targetKeywords -contains $ap.RegistryKeyword) {
                        Set-NetAdapterAdvancedProperty -Name $nic.Name -RegistryKeyword $ap.RegistryKeyword -RegistryValue 0 -NoRestart -ErrorAction SilentlyContinue
                    }
                }
                if (Get-Command Disable-NetAdapterPowerManagement -ErrorAction SilentlyContinue) {
                    Disable-NetAdapterPowerManagement -Name $nic.Name -NoRestart -ErrorAction SilentlyContinue
                }
            }
        } | Out-Null
    }
    else {
        $cap = Get-CapturedState -Id $stateKey
        Invoke-Mutation -Description 'Restaurar propriedades originais de energia do adaptador de rede' -Action {
            if ($cap -and $cap.captured) {
                foreach ($item in $cap.captured) {
                    if ($item.adapter -and $item.keyword -and $null -ne $item.value) {
                        Set-NetAdapterAdvancedProperty -Name $item.adapter -RegistryKeyword $item.keyword -RegistryValue $item.value -NoRestart -ErrorAction SilentlyContinue
                    }
                }
            }
            if (Get-Command Enable-NetAdapterPowerManagement -ErrorAction SilentlyContinue) {
                $adapters = Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Up' }
                foreach ($nic in $adapters) {
                    Enable-NetAdapterPowerManagement -Name $nic.Name -NoRestart -ErrorAction SilentlyContinue
                }
            }
        } | Out-Null
        Remove-CapturedState -Id $stateKey
    }
}

function Disable-RiotClientStartup {
    [CmdletBinding()]
    param(
        [ValidateSet('Apply', 'Undo')]
        [string]$Mode = 'Apply'
    )

    $runKey = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'
    $approvedKey = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run'
    $stateKey = 'Val_RiotClient_Cleanup'

    $entryNames = New-Object 'System.Collections.Generic.List[string]'
    if (Test-Path -LiteralPath $runKey) {
        $runItem = Get-Item -LiteralPath $runKey -ErrorAction SilentlyContinue
        if ($runItem) {
            foreach ($vn in $runItem.GetValueNames()) {
                $val = [string]$runItem.GetValue($vn, '')
                if ($vn -match '(?i)RiotClient' -or $val -match '(?i)RiotClientServices\.exe') {
                    [void]$entryNames.Add($vn)
                }
            }
        }
    }
    if ($entryNames.Count -eq 0) {
        [void]$entryNames.Add('RiotClient')
    }

    if ($Mode -eq 'Apply') {
        $capList = New-Object 'System.Collections.Generic.List[hashtable]'
        foreach ($en in $entryNames) {
            $curState = Get-RegistryEntryState -Path $approvedKey -Name $en -FallbackType 'Binary'
            [void]$capList.Add(@{
                kind    = 'startupApproved'
                name    = $en
                existed = $curState.ValueExisted
                value   = if ($curState.Value) { [Convert]::ToBase64String([byte[]]$curState.Value) } else { $null }
            })
        }
        Save-CapturedState -Id $stateKey -CapturedItems $capList.ToArray()

        $disabledBytes = [byte[]](0x03, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00)
        Invoke-Mutation -Description "Desativar inicializa$([char]0x00E7)$([char]0x00E3)o autom$([char]0x00E1)tica do Riot Client via StartupApproved (mantendo Vanguard intacto)" -Action {
            if (-not (Test-Path -LiteralPath $approvedKey)) {
                New-Item -Path $approvedKey -Force | Out-Null
            }
            foreach ($en in $entryNames) {
                Set-ItemProperty -LiteralPath $approvedKey -Name $en -Value $disabledBytes -Type Binary -Force -ErrorAction Stop
            }
        } | Out-Null
    }
    else {
        $cap = Get-CapturedState -Id $stateKey
        $enabledBytes = [byte[]](0x02, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00)
        Invoke-Mutation -Description "Reativar inicializa$([char]0x00E7)$([char]0x00E3)o autom$([char]0x00E1)tica do Riot Client no StartupApproved" -Action {
            if ($cap -and $cap.captured) {
                foreach ($item in $cap.captured) {
                    if ($item.existed -and $item.value) {
                        $origBytes = [Convert]::FromBase64String([string]$item.value)
                        Set-ItemProperty -LiteralPath $approvedKey -Name $item.name -Value $origBytes -Type Binary -Force -ErrorAction SilentlyContinue
                    }
                    elseif (Test-Path -LiteralPath $approvedKey) {
                        Set-ItemProperty -LiteralPath $approvedKey -Name $item.name -Value $enabledBytes -Type Binary -Force -ErrorAction SilentlyContinue
                    }
                }
            }
        } | Out-Null
        Remove-CapturedState -Id $stateKey
    }
}

function Clear-ShaderCache {
    [CmdletBinding()]
    param(
        [string[]]$TargetDirectories
    )

    if (-not $TargetDirectories -or $TargetDirectories.Count -eq 0) {
        $TargetDirectories = @(
            (Join-Path $env:LOCALAPPDATA 'D3DSCache'),
            (Join-Path $env:LOCALAPPDATA 'NVIDIA\DXCache'),
            (Join-Path $env:LOCALAPPDATA 'NVIDIA\GLCache'),
            (Join-Path $env:LOCALAPPDATA 'AMD\DxCache'),
            (Join-Path $env:LOCALAPPDATA 'AMD\DxcCache')
        )
    }

    Invoke-Mutation -Description "Limpar diret$([char]0x00F3)rios de Cache de Shaders (DirectX, NVIDIA e AMD)" -Action {
        $freedBytes = [int64]0
        $deletedCount = 0

        foreach ($dir in $TargetDirectories) {
            if (-not (Test-Path -LiteralPath $dir)) {
                continue
            }
            $files = Get-ChildItem -LiteralPath $dir -Recurse -File -Force -ErrorAction SilentlyContinue
            foreach ($f in $files) {
                $len = $f.Length
                try {
                    Remove-Item -LiteralPath $f.FullName -Force -ErrorAction Stop
                    $freedBytes += $len
                    $deletedCount++
                }
                catch {
                    Write-Verbose ("Arquivo de cache em uso (ignorado): {0}" -f $f.FullName)
                }
            }
        }

        $freedMb = [math]::Round(($freedBytes / 1MB), 2)
        Write-OptimizerLog -Level OK -Message ("Cache de Shaders limpo: {0} arquivos removidos ({1} MB liberados)." -f $deletedCount, $freedMb)
    } | Out-Null
}

function Invoke-GameOptimization {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$ProfileConfig,

        [Parameter(Mandatory = $true)]
        [pscustomobject]$Optimization,

        [ValidateSet('Apply', 'Undo')]
        [string]$Mode = 'Apply',

        [string]$CustomExePath
    )

    $action = $Optimization.action
    if ($script:AllowedGameActions -notcontains $action) {
        $msg = "Action '$action' na otimiza$([char]0x00E7)$([char]0x00E3)o '$($Optimization.id)' n$([char]0x00E3)o consta na whitelist do game-engine."
        Write-OptimizerLog -Level ERROR -Message $msg
        throw $msg
    }

    switch ($action) {
        'Set-AppCompatFlags' {
            $exe = if ($CustomExePath) { $CustomExePath } else { Find-GameExecutable -ProfileConfig $ProfileConfig }
            if ([string]::IsNullOrWhiteSpace($exe)) {
                Write-OptimizerLog -Level WARN -Message ("Execut$([char]0x00E1)vel de {0} n$([char]0x00E3)o encontrado para aplicar '{1}'." -f $ProfileConfig.gameName, $Optimization.title)
                return $false
            }
            $flags = if ($Optimization.flags) { $Optimization.flags } else { '~ DISABLEDXMAXIMIZEDWINDOWEDMODE HIGHDPIAWARE' }
            Set-AppCompatFlags -ExecutablePath $exe -Flags $flags -StateKey $Optimization.id -Mode $Mode
            return $true
        }
        'Set-DirectXGpuPreference' {
            $exe = if ($CustomExePath) { $CustomExePath } else { Find-GameExecutable -ProfileConfig $ProfileConfig }
            if ([string]::IsNullOrWhiteSpace($exe)) {
                Write-OptimizerLog -Level WARN -Message ("Execut$([char]0x00E1)vel de {0} n$([char]0x00E3)o encontrado para aplicar '{1}'." -f $ProfileConfig.gameName, $Optimization.title)
                return $false
            }
            Set-DirectXGpuPreference -ExecutablePath $exe -StateKey $Optimization.id -Mode $Mode
            return $true
        }
        'Optimize-NetworkAdapterGaming' {
            Optimize-NetworkAdapterGaming -Mode $Mode
            return $true
        }
        'Disable-RiotClientStartup' {
            Disable-RiotClientStartup -Mode $Mode
            return $true
        }
        'Clear-ShaderCache' {
            if ($Mode -eq 'Apply') {
                Clear-ShaderCache
            }
            else {
                Write-OptimizerLog -Level INFO -Message "A limpeza de Cache de Shaders $([char]0x00E9) uma opera$([char]0x00E7)$([char]0x00E3)o de manuten$([char]0x00E7)$([char]0x00E3)o (o driver recria o cache automaticamente)."
            }
            return $true
        }
        'Optimize-UsbPower' {
            if ($Mode -eq 'Apply') {
                Optimize-UsbPower
            }
            else {
                Restore-UsbPower
            }
            return $true
        }
    }

    return $false
}

function Test-GameOptimizationApplied {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [pscustomobject]$ProfileConfig,

        [Parameter(Mandatory = $true)]
        [pscustomobject]$Optimization,

        [string]$CustomExePath
    )

    switch ($Optimization.action) {
        'Set-AppCompatFlags' {
            $exe = if ($CustomExePath) { $CustomExePath } else { Find-GameExecutable -ProfileConfig $ProfileConfig }
            if ([string]::IsNullOrWhiteSpace($exe)) { return $false }
            $layersKey = 'HKCU:\Software\Microsoft\Windows NT\CurrentVersion\AppCompatFlags\Layers'
            $st = Get-RegistryEntryState -Path $layersKey -Name $exe -FallbackType 'String'
            return ($st.ValueExisted -and ($st.Value -match 'DISABLEDXMAXIMIZEDWINDOWEDMODE'))
        }
        'Set-DirectXGpuPreference' {
            $exe = if ($CustomExePath) { $CustomExePath } else { Find-GameExecutable -ProfileConfig $ProfileConfig }
            if ([string]::IsNullOrWhiteSpace($exe)) { return $false }
            $gpuKey = 'HKCU:\Software\Microsoft\DirectX\UserGpuPreferences'
            $st = Get-RegistryEntryState -Path $gpuKey -Name $exe -FallbackType 'String'
            return ($st.ValueExisted -and ($st.Value -match 'GpuPreference=2'))
        }
        'Optimize-NetworkAdapterGaming' {
            return ($null -ne (Get-CapturedState -Id 'NetworkAdapterGaming'))
        }
        'Disable-RiotClientStartup' {
            $approvedKey = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run'
            $st = Get-RegistryEntryState -Path $approvedKey -Name 'RiotClient' -FallbackType 'Binary'
            if ($st.ValueExisted -and $st.Value -is [byte[]] -and $st.Value.Length -ge 1) {
                return ($st.Value[0] -eq 0x03)
            }
            return ($null -ne (Get-CapturedState -Id 'Val_RiotClient_Cleanup'))
        }
        'Optimize-UsbPower' {
            return (Test-UsbPowerOptimized)
        }
        default {
            return $false
        }
    }
}

# ============================================================================
# Module: src/windows/modules/maintenance.ps1
# ============================================================================
# Ferramentas de Manuten--o e Reparo: Reset de Rede/DNS, SFC/DISM com cancelamento e Limpeza de Tempor-rios

function Invoke-NativeStep {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$FilePath,

        [string[]]$ArgumentList = @(),

        [Parameter(Mandatory = $true)]
        [string]$StepName
    )

    Write-OptimizerLog -Level INFO -Message ("Executando {0}..." -f $StepName)
    $proc = Start-Process -FilePath $FilePath -ArgumentList $ArgumentList -NoNewWindow -Wait -PassThru
    if ($proc.ExitCode -ne 0) {
        throw ("{0} falhou (c$([char]0x00F3)digo de sa$([char]0x00ED)da {1})." -f $StepName, $proc.ExitCode)
    }
}

function Invoke-NetworkReset {
    [CmdletBinding()]
    param()

    Invoke-Mutation -Description 'Resetar pilha de rede (Winsock, TCP/IP e Cache DNS)' -Action {
        Invoke-NativeStep -FilePath 'ipconfig.exe' -ArgumentList @('/flushdns') -StepName 'Limpeza do cache DNS'
        Invoke-NativeStep -FilePath 'netsh.exe' -ArgumentList @('winsock', 'reset') -StepName 'Reset do Winsock'
        Invoke-NativeStep -FilePath 'netsh.exe' -ArgumentList @('int', 'ip', 'reset') -StepName 'Reset do TCP/IP'

        Write-OptimizerLog -Level OK -Message 'Pilha de rede e DNS redefinidos com sucesso. Reinicie o computador para concluir.'
    } | Out-Null
}

function Invoke-CancelableProcess {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]
        [string]$FilePath,

        [Parameter(Mandatory = $true)]
        [string]$Arguments,

        [Parameter(Mandatory = $true)]
        [string]$StepName,

        [int[]]$SuccessExitCodes = @(0)
    )

    $psi = New-Object System.Diagnostics.ProcessStartInfo
    $psi.FileName = $FilePath
    $psi.Arguments = $Arguments
    $psi.UseShellExecute = $false
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true
    $psi.CreateNoWindow = $true

    $proc = New-Object System.Diagnostics.Process
    $proc.StartInfo = $psi

    [void]$proc.Start()
    while (-not $proc.HasExited) {
        $cancel = ($script:OptiKit -and $script:OptiKit.CancelRequest) -or
                  ($script:OptiKit -and $script:OptiKit.SyncHash -and $script:OptiKit.SyncHash.CancelRequest)
        if ($cancel) {
            try {
                $proc.Kill()
            }
            catch {
                Write-Verbose ("Erro ao encerrar processo cancelado: {0}" -f $_.Exception.Message)
            }
            Write-OptimizerLog -Level WARN -Message ("Execu$([char]0x00E7)$([char]0x00E3)o de {0} cancelada pelo usu$([char]0x00E1)rio." -f $StepName)
            return $false
        }

        while (-not $proc.StandardOutput.EndOfStream) {
            $line = $proc.StandardOutput.ReadLine()
            if (-not [string]::IsNullOrWhiteSpace($line)) {
                $cleanLine = ($line -replace "`0", '').Trim()
                if ($cleanLine.Length -gt 0) {
                    Write-OptimizerLog -Level INFO -Message ("[{0}] {1}" -f $StepName, $cleanLine)
                }
            }
        }
        Start-Sleep -Milliseconds 200
    }

    return ($SuccessExitCodes -contains $proc.ExitCode)
}

function Invoke-SystemIntegrityRepair {
    [CmdletBinding()]
    param()

    if ($script:OptiKit) {
        $script:OptiKit.CancelRequest = $false
        if ($script:OptiKit.SyncHash) {
            $script:OptiKit.SyncHash.CancelRequest = $false
        }
    }

    Invoke-Mutation -Description "Executar verifica$([char]0x00E7)$([char]0x00E3)o e reparo de imagem do sistema (DISM /RestoreHealth + SFC /scannow)" -Action {
        $canceled = {
            ($script:OptiKit -and $script:OptiKit.CancelRequest) -or
            ($script:OptiKit -and $script:OptiKit.SyncHash -and $script:OptiKit.SyncHash.CancelRequest)
        }

        Write-OptimizerLog -Level INFO -Message 'Etapa 1/2: Executando DISM /Online /Cleanup-Image /RestoreHealth (pode levar de 5 a 15 minutos)...'
        $dismOk = Invoke-CancelableProcess -FilePath 'DISM.exe' -Arguments '/Online /Cleanup-Image /RestoreHealth' -StepName 'DISM' -SuccessExitCodes @(0, 3010)
        if (-not $dismOk) {
            if (& $canceled) {
                throw "Execu$([char]0x00E7)$([char]0x00E3)o cancelada pelo usu$([char]0x00E1)rio durante o DISM; SFC n$([char]0x00E3)o foi executado."
            }
            throw "DISM /RestoreHealth falhou; SFC n$([char]0x00E3)o foi executado."
        }

        Write-OptimizerLog -Level INFO -Message 'Etapa 2/2: Executando SFC /scannow...'
        $sfcOk = Invoke-CancelableProcess -FilePath 'sfc.exe' -Arguments '/scannow' -StepName 'SFC'
        if (-not $sfcOk) {
            if (& $canceled) {
                throw "Execu$([char]0x00E7)$([char]0x00E3)o cancelada pelo usu$([char]0x00E1)rio durante o SFC."
            }
            throw "SFC /scannow retornou c$([char]0x00F3)digo de falha."
        }

        Write-OptimizerLog -Level OK -Message "Verifica$([char]0x00E7)$([char]0x00E3)o de integridade SFC/DISM finalizada."
    } | Out-Null
}

function Clear-OptiKitDirectory {
    [CmdletBinding()]
    param(
        [string[]]$TargetDirectories
    )

    $freedBytes = [int64]0
    $deletedFiles = 0
    $failedFiles = 0

    foreach ($dir in @($TargetDirectories)) {
        if (-not $dir -or -not (Test-Path -LiteralPath $dir)) {
            continue
        }

        $files = Get-ChildItem -LiteralPath $dir -Recurse -File -Force -ErrorAction SilentlyContinue
        foreach ($file in $files) {
            $length = $file.Length
            try {
                Remove-Item -LiteralPath $file.FullName -Force -ErrorAction Stop
                $freedBytes += $length
                $deletedFiles++
            }
            catch {
                $failedFiles++
                Write-Verbose ("Arquivo em uso (ignorado): {0}" -f $file.FullName)
            }
        }
    }

    return [pscustomobject]@{
        DeletedFiles = $deletedFiles
        FailedFiles  = $failedFiles
        FreedBytes   = $freedBytes
    }
}

function Clear-TemporaryFiles {
    [CmdletBinding()]
    param(
        [string[]]$TargetDirectories
    )

    if (-not $TargetDirectories -or $TargetDirectories.Count -eq 0) {
        $TargetDirectories = @(
            $env:TEMP,
            (Join-Path $env:SystemRoot 'Temp')
        ) | Select-Object -Unique
    }

    Invoke-Mutation -Description "Limpar arquivos tempor$([char]0x00E1)rios do usu$([char]0x00E1)rio (%TEMP%) e do sistema (Windows\Temp)" -Action {
        $result = Clear-OptiKitDirectory -TargetDirectories $TargetDirectories
        $freedMb = [math]::Round(($result.FreedBytes / 1MB), 2)
        Write-OptimizerLog -Level OK -Message ("Limpeza conclu$([char]0x00ED)da: {0} arquivos tempor$([char]0x00E1)rios removidos ({1} MB liberados)." -f $result.DeletedFiles, $freedMb)
        if ($result.FailedFiles -gt 0) {
            Write-OptimizerLog -Level WARN -Message ("{0} arquivo(s) tempor$([char]0x00E1)rio(s) estavam em uso e foram ignorados." -f $result.FailedFiles)
        }
    } | Out-Null
}

function Invoke-AdvancedCleanup {
    [CmdletBinding()]
    param(
        [string]$WindowsUpdateCache = (Join-Path $env:SystemRoot 'SoftwareDistribution\Download'),
        [string]$PrefetchDirectory = (Join-Path $env:SystemRoot 'Prefetch'),
        [switch]$SkipComponentStore,
        [switch]$SkipDeliveryOptimization,
        [switch]$SkipRecycleBin
    )

    Invoke-Mutation -Description "Limpeza avan$([char]0x00E7)ada (Windows Update, Delivery Optimization, lixeira, prefetch e Component Store)" -Action {
        $failedSteps = New-Object 'System.Collections.Generic.List[string]'
        $freedBytes = [int64]0
        $deletedFiles = 0

        $fileResult = Clear-OptiKitDirectory -TargetDirectories @($WindowsUpdateCache, $PrefetchDirectory)
        $freedBytes += $fileResult.FreedBytes
        $deletedFiles += $fileResult.DeletedFiles
        if ($fileResult.FailedFiles -gt 0) {
            Write-OptimizerLog -Level WARN -Message ("{0} arquivo(s) de cache estavam em uso e foram ignorados." -f $fileResult.FailedFiles)
        }

        if (-not $SkipRecycleBin) {
            if (Get-Command Clear-RecycleBin -ErrorAction SilentlyContinue) {
                try {
                    Clear-RecycleBin -Force -ErrorAction Stop
                    Write-OptimizerLog -Level OK -Message 'Lixeira esvaziada.'
                }
                catch {
                    [void]$failedSteps.Add('Lixeira')
                    Write-OptimizerLog -Level WARN -Message ("Falha ao esvaziar a lixeira: {0}" -f $_.Exception.Message)
                }
            }
            else {
                Write-OptimizerLog -Level INFO -Message "Clear-RecycleBin indispon$([char]0x00ED)vel nesta vers$([char]0x00E3)o do Windows (ignorado)."
            }
        }

        if (-not $SkipDeliveryOptimization) {
            if (Get-Command Delete-DeliveryOptimizationCache -ErrorAction SilentlyContinue) {
                try {
                    Delete-DeliveryOptimizationCache -Force -ErrorAction Stop
                    Write-OptimizerLog -Level OK -Message 'Cache do Delivery Optimization removido.'
                }
                catch {
                    [void]$failedSteps.Add('Delivery Optimization')
                    Write-OptimizerLog -Level WARN -Message ("Falha ao limpar o Delivery Optimization: {0}" -f $_.Exception.Message)
                }
            }
            else {
                Write-OptimizerLog -Level INFO -Message "Delete-DeliveryOptimizationCache indispon$([char]0x00ED)vel (ignorado)."
            }
        }

        if (-not $SkipComponentStore) {
            try {
                $dismOk = Invoke-CancelableProcess -FilePath 'DISM.exe' -Arguments '/Online /Cleanup-Image /StartComponentCleanup' -StepName 'Component Store (DISM)' -SuccessExitCodes @(0, 3010)
                if (-not $dismOk) {
                    throw 'DISM /StartComponentCleanup falhou ou foi cancelado.'
                }
            }
            catch {
                [void]$failedSteps.Add('Component Store')
                Write-OptimizerLog -Level WARN -Message ("Falha na limpeza do Component Store: {0}" -f $_.Exception.Message)
            }
        }

        $freedMb = [math]::Round(($freedBytes / 1MB), 2)
        $summaryLevel = if ($failedSteps.Count -gt 0) { 'WARN' } else { 'OK' }
        Write-OptimizerLog -Level $summaryLevel -Message ("Limpeza avan$([char]0x00E7)ada conclu$([char]0x00ED)da: {0} arquivo(s) removido(s) ({1} MB liberados)." -f $deletedFiles, $freedMb)

        if ($failedSteps.Count -gt 0) {
            throw ("Limpeza avan$([char]0x00E7)ada conclu$([char]0x00ED)da com falha em: {0}" -f ($failedSteps -join '; '))
        }
    } | Out-Null
}

function Set-OptiKitTargetRelease {
    [CmdletBinding()]
    param()

    $wuKey = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate'
    $cv = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop
    $displayVersion = [string]$cv.DisplayVersion
    if ([string]::IsNullOrWhiteSpace($displayVersion)) {
        throw "N$([char]0x00E3)o foi poss$([char]0x00ED)vel ler DisplayVersion do Windows."
    }

    $productVersion = if ([string]$cv.ProductName -match 'Windows 11') {
        'Windows 11'
    }
    elseif ([string]$cv.ProductName -match 'Windows 10') {
        'Windows 10'
    }
    else {
        throw "ProductName do Windows n$([char]0x00E3)o reconhecido."
    }

    $captured = New-Object 'System.Collections.Generic.List[hashtable]'
    foreach ($name in @('ProductVersion', 'TargetReleaseVersion', 'TargetReleaseVersionInfo')) {
        $state = Get-RegistryEntryState -Path $wuKey -Name $name -FallbackType 'DWord'
        [void]$captured.Add(@{
            kind       = 'registry'
            path       = $wuKey
            name       = $name
            keyExisted = [bool]$state.KeyExisted
            existed    = [bool]$state.ValueExisted
            type       = $state.Type
            value      = $state.Value
        })
    }
    Save-CapturedState -Id 'TargetReleaseVersion' -CapturedItems $captured.ToArray()

    Invoke-Mutation -Description ("Fixar feature updates em {0} ({1})" -f $displayVersion, $productVersion) -Action {
        Set-RegistryEntryValue -Path $wuKey -Name 'ProductVersion' -Type 'String' -Value $productVersion
        Set-RegistryEntryValue -Path $wuKey -Name 'TargetReleaseVersion' -Type 'DWord' -Value 1
        Set-RegistryEntryValue -Path $wuKey -Name 'TargetReleaseVersionInfo' -Type 'String' -Value $displayVersion
    } | Out-Null

    if ($script:OptiKit -and $script:OptiKit.DryRun) {
        return
    }

    if (-not (Test-OptiKitTargetRelease)) {
        throw "TargetReleaseVersion n$([char]0x00E3)o ficou efetivo; verifique pol$([char]0x00ED)ticas de GPO."
    }
}

function Restore-OptiKitTargetRelease {
    [CmdletBinding()]
    param()

    $captured = Get-CapturedState -Id 'TargetReleaseVersion'
    $capturedList = if ($captured -and $captured.captured) { @($captured.captured) } else { @() }

    Invoke-Mutation -Description "Remover fixa$([char]0x00E7)$([char]0x00E3)o de feature update (TargetReleaseVersion)" -Action {
        if ($capturedList.Count -gt 0) {
            foreach ($item in $capturedList) {
                if ($item.existed) {
                    Set-RegistryEntryValue -Path $item.path -Name $item.name -Type $item.type -Value $item.value
                }
                else {
                    Set-RegistryEntryValue -Path $item.path -Name $item.name -Type $item.type -Value '<RemoveEntry>'
                }
            }
        }
        else {
            $wuKey = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate'
            foreach ($name in @('ProductVersion', 'TargetReleaseVersion', 'TargetReleaseVersionInfo')) {
                Set-RegistryEntryValue -Path $wuKey -Name $name -Type 'String' -Value '<RemoveEntry>'
            }
        }
    } | Out-Null

    Remove-CapturedState -Id 'TargetReleaseVersion'
}

function Test-OptiKitTargetRelease {
    [CmdletBinding()]
    param()

    $wuKey = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate'
    $target = Get-RegistryEntryState -Path $wuKey -Name 'TargetReleaseVersion' -FallbackType 'DWord'
    $info = Get-RegistryEntryState -Path $wuKey -Name 'TargetReleaseVersionInfo' -FallbackType 'String'
    return ($target.ValueExisted -and ([int]$target.Value -eq 1) -and $info.ValueExisted -and -not [string]::IsNullOrWhiteSpace([string]$info.Value))
}

function Disable-OptiKitReservedStorage {
    [CmdletBinding()]
    param()

    $previous = $null
    try {
        if (Get-Command Get-WindowsReservedStorageState -ErrorAction SilentlyContinue) {
            $previous = [string](Get-WindowsReservedStorageState -ErrorAction Stop)
        }
    }
    catch {
        Write-Verbose ("Estado do Armazenamento Reservado indispon$([char]0x00ED)vel: {0}" -f $_.Exception.Message)
    }

    $wasEnabled = $true
    if ($previous -and $previous -match '(?i)Disabled|Desabilitado') {
        $wasEnabled = $false
    }

    Save-CapturedState -Id 'ReservedStorage' -CapturedItems @(
        @{ kind = 'reservedStorage'; wasEnabled = $wasEnabled; previous = $previous }
    )

    Invoke-Mutation -Description 'Desativar Armazenamento Reservado do Windows via DISM' -Action {
        $proc = Start-Process -FilePath 'DISM.exe' -ArgumentList @('/Online', '/Set-ReservedStorageState', '/State:Disabled') -NoNewWindow -Wait -PassThru
        if ($proc.ExitCode -ne 0) {
            throw ("DISM /Set-ReservedStorageState retornou c$([char]0x00F3)digo {0}" -f $proc.ExitCode)
        }
    } | Out-Null

    if ($script:OptiKit -and $script:OptiKit.DryRun) {
        return
    }

    $currentState = $null
    try {
        Import-Module -Name DISM -ErrorAction Stop
        $currentState = [string](Get-WindowsReservedStorageState -ErrorAction Stop)
    }
    catch {
        Write-OptimizerLog -Level WARN -Message ("N$([char]0x00E3)o foi poss$([char]0x00ED)vel verificar o estado do Armazenamento Reservado: {0}" -f $_.Exception.Message)
    }

    if (-not [string]::IsNullOrWhiteSpace($currentState) -and $currentState -notmatch '(?i)Disabled|Desabilitado') {
        throw ("Armazenamento Reservado n$([char]0x00E3)o ficou desabilitado (estado atual: {0})." -f $currentState)
    }
}

function Enable-OptiKitReservedStorage {
    [CmdletBinding()]
    param()

    $captured = Get-CapturedState -Id 'ReservedStorage'
    $targetState = 'Enabled'
    if ($captured -and $captured.captured -and $captured.captured.Count -gt 0 -and $captured.captured[0].wasEnabled -eq $false) {
        $targetState = 'Disabled'
    }

    Invoke-Mutation -Description ("Restaurar Armazenamento Reservado para {0}" -f $targetState) -Action {
        $proc = Start-Process -FilePath 'DISM.exe' -ArgumentList @('/Online', '/Set-ReservedStorageState', ("/State:{0}" -f $targetState)) -NoNewWindow -Wait -PassThru
        if ($proc.ExitCode -ne 0) {
            throw ("DISM /Set-ReservedStorageState retornou c$([char]0x00F3)digo {0}" -f $proc.ExitCode)
        }
    } | Out-Null

    if (-not ($script:OptiKit -and $script:OptiKit.DryRun)) {
        $currentState = $null
        try {
            Import-Module -Name DISM -ErrorAction Stop
            $currentState = [string](Get-WindowsReservedStorageState -ErrorAction Stop)
        }
        catch {
            Write-OptimizerLog -Level WARN -Message ("N$([char]0x00E3)o foi poss$([char]0x00ED)vel verificar o estado do Armazenamento Reservado: {0}" -f $_.Exception.Message)
        }

        if (-not [string]::IsNullOrWhiteSpace($currentState)) {
            $expectedPattern = if ($targetState -eq 'Enabled') { '(?i)Enabled|Habilitado' } else { '(?i)Disabled|Desabilitado' }
            if ($currentState -notmatch $expectedPattern) {
                throw ("Armazenamento Reservado n$([char]0x00E3)o ficou em {0} (estado atual: {1})." -f $targetState, $currentState)
            }
        }
    }

    Remove-CapturedState -Id 'ReservedStorage'
}

function Test-OptiKitReservedStorage {
    [CmdletBinding()]
    param()

    try {
        if (Get-Command Get-WindowsReservedStorageState -ErrorAction SilentlyContinue) {
            $state = [string](Get-WindowsReservedStorageState -ErrorAction Stop)
            return ($state -match '(?i)Disabled|Desabilitado')
        }
    }
    catch {
        return $false
    }
    return $false
}

function Test-OptiKitUpdateAvailable {
    [CmdletBinding()]
    param(
        [string]$RepoSlug = $script:OptiKitRepo,
        [string]$CurrentVersion = $script:OptiKitVersion
    )

    if ([string]::IsNullOrWhiteSpace($RepoSlug) -or [string]::IsNullOrWhiteSpace($CurrentVersion)) {
        return $null
    }

    try {
        $url = "https://raw.githubusercontent.com/$RepoSlug/main/VERSION"
        $raw = (Invoke-RestMethod -Uri $url -TimeoutSec 5 -UseBasicParsing).Trim()
        $remote = [version]$raw
        $local = [version]$CurrentVersion
        if ($remote -gt $local) {
            return [pscustomobject]@{
                Available = $true
                Version   = $remote.ToString()
                Url       = "https://github.com/$RepoSlug/releases/latest"
            }
        }
    }
    catch {
        Write-Verbose ("Verifica$([char]0x00E7)$([char]0x00E3)o de atualiza$([char]0x00E7)$([char]0x00E3)o indispon$([char]0x00ED)vel: {0}" -f $_.Exception.Message)
    }
    return $null
}

function Export-OptiKitReport {
    [CmdletBinding()]
    param(
        [string]$OutputDirectory,

        [object[]]$Diagnostics,

        [hashtable]$Counts
    )

    if ([string]::IsNullOrWhiteSpace($OutputDirectory)) {
        $OutputDirectory = Join-Path $script:OptiKit.DataRoot 'reports'
    }
    if (-not (Test-Path -LiteralPath $OutputDirectory)) {
        New-Item -Path $OutputDirectory -ItemType Directory -Force | Out-Null
    }

    $timestamp = Get-Date -Format 'yyyyMMdd-HHmmss'
    $path = Join-Path $OutputDirectory ("optikit-report-{0}.html" -f $timestamp)
    $hardware = Get-OptiKitHardware
    $state = Read-OptiKitStateFile
    $logLines = @($script:OptiKit.LogHistory)

    if ($null -eq $Diagnostics) {
        try {
            $Diagnostics = @(Get-OptiKitHardwareDiagnostics)
        }
        catch {
            $Diagnostics = @()
            Write-OptimizerLog -Level WARN -Message ("Diagn$([char]0x00F3)stico indispon$([char]0x00ED)vel no relat$([char]0x00F3)rio: {0}" -f $_.Exception.Message)
        }
    }
    else {
        $Diagnostics = @($Diagnostics)
    }

    $summaryCounts = if ($Counts) {
        $Counts
    }
    elseif ($script:OptiKit -and $script:OptiKit.SessionCounts) {
        $script:OptiKit.SessionCounts
    }
    else {
        @{}
    }

    $applied = if ($summaryCounts.ContainsKey('Applied')) { [int]$summaryCounts['Applied'] } else { 0 }
    $skipped = if ($summaryCounts.ContainsKey('Skipped')) { [int]$summaryCounts['Skipped'] } else { 0 }
    $failed = if ($summaryCounts.ContainsKey('Failed')) { [int]$summaryCounts['Failed'] } else { 0 }
    $diagOk = @($Diagnostics | Where-Object { $_.Status -eq 'OK' }).Count
    $diagWarn = @($Diagnostics | Where-Object { $_.Status -eq 'Warn' }).Count
    $diagErr = @($Diagnostics | Where-Object { $_.Status -eq 'Error' }).Count
    $diagInfo = @($Diagnostics | Where-Object { $_.Status -notin @('OK', 'Warn', 'Error') }).Count

    $encode = {
        param([string]$text)
        if ($null -eq $text) { return '' }
        return ($text -replace '&', '&amp;' -replace '<', '&lt;' -replace '>', '&gt;')
    }

    $sb = New-Object System.Text.StringBuilder
    [void]$sb.AppendLine('<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><title>OptiKit Report</title>')
    [void]$sb.AppendLine('<style>body{font-family:Segoe UI,Arial,sans-serif;background:#121212;color:#e4e4e7;padding:24px}table{border-collapse:collapse;width:100%;margin:12px 0}td,th{border:1px solid #3f3f46;padding:6px;text-align:left;vertical-align:top}th{background:#27272a;color:#00e5ff}pre{background:#0d0d10;padding:12px;overflow:auto;font-size:12px;white-space:pre-wrap}h1,h2{color:#00e5ff}summary{cursor:pointer;color:#00e5ff}</style></head><body>')
    [void]$sb.AppendLine(("<h1>OptiKit v{0} $([char]0x2014) Relat$([char]0x00F3)rio</h1>" -f (& $encode ([string]$script:OptiKitVersion))))
    [void]$sb.AppendLine(("<p><b>Data:</b> {0}<br><b>Hardware:</b> {1}</p>" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), (& $encode ([string]$hardware.Summary))))

    [void]$sb.AppendLine("<h2>Resumo da sess$([char]0x00E3)o</h2><table><tr><th>Opera$([char]0x00E7)$([char]0x00F5)es OK</th><th>Ignoradas</th><th>Falhas</th><th>Estados capturados</th><th>Diagn$([char]0x00F3)sticos</th></tr>")
    [void]$sb.AppendLine(("<tr><td>{0}</td><td>{1}</td><td>{2}</td><td>{3}</td><td>{4} ok | {5} avisos | {6} erros | {7} info</td></tr>" -f $applied, $skipped, $failed, $state.Count, $diagOk, $diagWarn, $diagErr, $diagInfo))
    [void]$sb.AppendLine('</table>')

    [void]$sb.AppendLine("<h2>Diagn$([char]0x00F3)stico de hardware</h2><table><tr><th>Status</th><th>Item</th><th>Resumo</th><th>Detalhe</th></tr>")
    if ($Diagnostics.Count -eq 0) {
        [void]$sb.AppendLine("<tr><td colspan=`"4`">Nenhum diagn$([char]0x00F3)stico dispon$([char]0x00ED)vel.</td></tr>")
    }
    else {
        foreach ($diag in $Diagnostics) {
            $detail = [string]$diag.Detail
            if (-not [string]::IsNullOrWhiteSpace([string]$diag.ActionText)) {
                $detail = ("{0} A$([char]0x00E7)$([char]0x00E3)o sugerida: {1}" -f $detail, $diag.ActionText).Trim()
            }
            [void]$sb.AppendLine(("<tr><td>{0}</td><td>{1}</td><td>{2}</td><td>{3}</td></tr>" -f (& $encode ([string]$diag.Status)), (& $encode ([string]$diag.Title)), (& $encode ([string]$diag.Summary)), (& $encode $detail)))
        }
    }
    [void]$sb.AppendLine('</table>')

    [void]$sb.AppendLine("<h2>Ajustes com estado capturado</h2><table><tr><th>ID</th><th>Aplicado em</th><th>Sess$([char]0x00E3)o</th><th>Valores capturados</th></tr>")
    if ($state.Count -eq 0) {
        [void]$sb.AppendLine('<tr><td colspan="4">Nenhum estado capturado.</td></tr>')
    }
    else {
        foreach ($key in $state.Keys) {
            $record = $state[$key]
            $capturedJson = ''
            if ($record -and @($record.captured).Count -gt 0) {
                try {
                    $capturedJson = ($record.captured | ConvertTo-Json -Depth 8 -Compress)
                }
                catch {
                    $capturedJson = [string]$_.Exception.Message
                }
            }
            $capturedCell = if ([string]::IsNullOrWhiteSpace($capturedJson)) {
                "$([char]0x2014)"
            }
            else {
                ("<details><summary>ver</summary><pre>{0}</pre></details>" -f (& $encode $capturedJson))
            }
            [void]$sb.AppendLine(("<tr><td>{0}</td><td>{1}</td><td>{2}</td><td>{3}</td></tr>" -f (& $encode ([string]$key)), (& $encode ([string]$record.appliedAt)), (& $encode ([string]$record.session)), $capturedCell))
        }
    }

    [void]$sb.AppendLine("</table><h2>Log da sess$([char]0x00E3)o</h2><pre>")
    [void]$sb.AppendLine((& $encode (($logLines -join [Environment]::NewLine))))
    [void]$sb.AppendLine('</pre></body></html>')

    $utf8Bom = New-Object System.Text.UTF8Encoding($true)
    [System.IO.File]::WriteAllText($path, $sb.ToString(), $utf8Bom)
    Write-OptimizerLog -Level OK -Message ("Relat$([char]0x00F3)rio exportado: {0}" -f $path)
    return $path
}

